        Ext._create('core.GridSelectWindow', {
            'rest': 'rh.bank.BankRestful',
            'title': 'Selecione um banco para filtrar',
            'width': Ext.getBody().getBox().width * 0.9,
            'height': Ext.getBody().getBox().height * 0.9,
            'callback': {
                'scope': this,
                'fn': function(instance) {
                    if(instance)
                        this.setFilterProperty("banco", instance.get('pk'), 1003);
                    else
                        this.removeFilterProperty('banco', 1003);
                }
            }
        }).show();
