        if(!this._filterTipoConta)
            this._filterTipoConta = [1, 2, 3];

        if(this._filterTipoConta.indexOf(tipo) >= 0)
            this._filterTipoConta.remove(tipo);
        else
            this._filterTipoConta.push(tipo);

        this.setFilterProperty('tipo_conta__in', this._filterTipoConta, 1000);
