Ext._define('rh.publicacao.Restful', {
    extend: 'core.Restful',

    resource: 'RHPublicacaoRestful',

    sentToPublication: function(id, values, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute('sent_to_publication', id, 'POST', {
                params: values,
                scope: this,
                callback: function() {
                    core.invokeCallback(cbCallback || {});
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success)
                        core.invokeCallback(cbSuccess || {});
                    else
                        core.invokeCallback(cbFailure || {}, rst.message);
                },
                failure: function() {
                    core.invokeCallback((cbFailure || {}), 'Recurso indisponivel no momento.');
                }
            })
        );
    },

    confirmPublication: function(id, values, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute('confirm_publication', id, 'POST', {
                params: values,
                scope: this,
                callback: function() {
                    core.invokeCallback(cbCallback || {});
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success)
                        core.invokeCallback(cbSuccess || {});
                    else
                        core.invokeCallback(cbFailure || {}, rst.message);
                },
                failure: function() {
                    core.invokeCallback((cbFailure || {}), 'Recurso indisponivel no momento.');
                }
            })
        );
    },

    getFields: function() {
        var fields = rh.publicacao.Restful.superclass.getFields.call(this);
        return fields.concat([
            {name: 'tipo', type: 'int'},
            {name: 'icons', type: 'auto'},
            {name: 'tipo_display', type: 'string'},
            {name: 'numero', type: 'string'},
            {name: 'ano', type: 'string'},
            {name: 'data_expedicao', type: 'date', dateFormat: 'd/m/Y'},
            {name: 'lei_autorizativa', type: ''},
            {name: 'vehicle_page', type: 'int', useNull: true},
            {name: 'veiculo_publicacao', type: 'int', useNull: true},
            {name: 'veiculo_publicacao_display', type: 'string'},
            {name: 'publication_state', type: 'int', useNull: true},
            {name: 'publication_state_display', type: 'string'},
            {name: 'arquivo', type: 'int', useNull: true},
            {name: 'arquivo_unicode', type: 'string'},
            {name: 'origem', type: 'int', useNull: true},
            {name: 'origem_unicode', type: 'string'},
            {name: 'numero_publicacao', type: 'string'},
            {name: 'data_publicacao', type: 'date', dateFormat: 'd/m/Y'},
            {name: 'data_vigencia', type: 'date', dateFormat: 'd/m/Y'},
            {name: 'interno', type: 'boolean'},
            {name: 'indirect', type: 'boolean'},
            {name: 'interessado_nome', type: 'string'},
            {name: 'observacao', type: 'string'},
            {name: 'cache_unicode', type: 'string'},
            {name: 'document', type: 'string'},
            {name: 'formated_content', type: 'string'},
            {name: 'document_read_only', type: 'bool'},
        ]);
    }
});

/*
 * src: /app/root/rh/static/publicacao/Window.js
 */
Ext._define('rh.publicacao.Window', {
    extend: 'core.RestfulWindow',

    rest: 'rh.publicacao.Restful',

    width: 820,

    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                items: [{
                    xtype: 'tabpanel',
                    height: 760,
                    activeItem: 0,
                    border: false,
                    items: [
                        this.getPublicacaoPanel(),
                        // this.getPublicacaoSite(),
                        this.getDocumentPanel()
                    ]
                }]
            });


        return this._formPanel;
    },

    enablePublicacaoOficial: function(enabled){
        var form = this.getFormPanel().getForm();
        var numero_pub, data_pub;

        numero_pub = form.findField('numero_publicacao');
        data_pub = form.findField('data_publicacao');

        if(enabled) {
            numero_pub.enable();
            data_pub.enable();
        }
        else {
            numero_pub.disable();
            data_pub.disable();
        }
    },

    getPublicacaoSite: function(cfg) {
        if(!this._publicacaoSite)
            this._publicacaoSite = Ext._create('Ext.Panel', {
                title: 'Site',
                layout: {
                    type: 'hbox',
                    align: 'stretch'
                },
                items: [
                    {
                        xtype: 'ckeditor',
                        name: 'observacao',
                        height: 283
                    }
                ]
            });

        return this._publicacaoSite;
    },

    getDocumentField: function() {
        if(!this._documentField)
            this._documentField = Ext._create('toolkit.fields.CKEditor', {
                name: 'document',
                height: 283
            });

        return this._documentField;
    },

    getDocumentPanel: function(cfg) {
        if(!this._documentPanel)
            this._documentPanel = Ext._create('Ext.Panel', {
                title: 'Conteúdo do documento',
                layout: {
                    type: 'hbox',
                    align: 'stretch'
                },
                items: [
                    this.getDocumentField()
                ]
            });

        return this._documentPanel;
    },

    getPublicacaoPanel: function() {
        if(!this._eventPanel)
            this._eventPanel = Ext._create('Ext.Panel', {
                frame: true,
                border: false,
                defaults: {
                    width: 680
                },
                title: 'Dados',
                layout: 'form',
                items: [
                    {
                        fieldLabel: 'Número',
                        xtype: 'textfield',
                        name: 'numero',
                        allowBlank: false
                    },{
                        fieldLabel: 'Tipo',
                        xtype: 'choicefield',
                        hiddenName: 'tipo',
                        choiceId: 'rh.TIPO_DOCUMENTO',
                        allowBlank: false,
                    },
                    {
                        xtype: 'rest-autocompletefield',
                        fieldLabel: 'Origem',
                        allowBlank: false,
                        rest: 'rh.generalorgan.Restful',
                        name: 'origem'
                    },
                    {
                        fieldLabel: 'Expedição',
                        xtype: 'datefield',
                        name: 'data_expedicao',
                        allowBlank: false
                    },{
                        fieldLabel: 'Vigência',
                        xtype: 'datefield',
                        name: 'data_vigencia',
                        allowBlank: false
                    },{
                        fieldLabel: 'Interno',
                        xtype: 'checkbox',
                        name: 'interno',
                    },{
                        xtype:'fieldset',
                        title: 'Veículo de Publicação',
                        collapsible: false,
                        checkboxToggle: {
                            tag: 'input',
                            type: 'checkbox',
                            name: this.checkboxName || this.id+'-checkbox'
                        },
                        autoHeight: true,
                        width: 790,
                        defaults: {
                            width: 660
                        },
                        items :[
                            {
                                xtype: 'choicefield',
                                fieldLabel: 'Veiculo de Publicação',
                                hiddenName: 'veiculo_publicacao',
                                width: 550,
                                choiceId: 'rh.VEICULO_PUBLICACAO'
                            }, {
                                fieldLabel: 'Número',
                                xtype: 'textfield',
                                name: 'numero_publicacao',
                                allowBlank: true,
                                width: 200
                            }, {
                                fieldLabel: 'Publicado',
                                xtype: 'datefield',
                                name: 'data_publicacao',
                                allowBlank: true,
                                width: 100
                            }, {
                                fieldLabel: 'Página',
                                xtype: 'numberfield',
                                name: 'vehicle_page',
                                allowBlank: true,
                                width: 100
                            }
                        ]
                    },{
                        fieldLabel: 'Interessado',
                        xtype: 'textfield',
                        name: 'interessado_nome',
                        allowBlank: true,
                    },{
                        fieldLabel: 'Arquivo',
                        xtype: 'ged-fileuploadfield',
                        name: 'arquivo',
                        allowBlank: true,
                    },
                    {
                        fieldLabel: 'Site',
                        xtype: 'ckeditor',
                        name: 'observacao',
                        height: 200
                    }
                ]
            });

        return this._eventPanel;
    },

    documentReadOnly: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._documentReadOnly = value;

            if(dispatch)
                this.observeDocumentReadOnly();
        }

        return this._documentReadOnly;
    },

    observeDocumentReadOnly: function() {
        value = this.documentReadOnly();

        if(value) {
            this.getDocumentPanel().disable();
        }
        else {
            this.getDocumentPanel().enable();
        }
    },

    'constructor': function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(cfg, {
            'disableSaveAndNew': true,
            'saveAndContinue': {
                'scope': this,
                'fn': function(instance) {
                    this.oId = instance.pk;
                    this.documentReadOnly(instance.document_read_only);
                    this.action = 'update';
                }
            }
        });

        rh.publicacao.Window.superclass.constructor.call(this, cfg);
        if((cfg.values || {}).document_read_only !== undefined)
            this.documentReadOnly(cfg.values.document_read_only);
    }

});

