/**
 *
 **/
Ext._define('rh.prorrogacao.Window', {
    extend: 'core.RestfulWindow',

    rest: 'rh.prorrogacao.Restful',

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                {
                    allowBlank: false,
                    fieldLabel: "Data Início *",
                    name: "data_inicio",
                    xtype: "datefield"
                },
                {
                    allowBlank: false,
                    fieldLabel: "Data Fim *",
                    name: "data_fim",
                    xtype: "datefield"
                },
                {
                    xtype: "rest-autocompletefield",
                    fieldLabel: "Publicação *",
                    allowBlank: false,
                    rest: "rh.publicacao.Restful",
                    name: "publicacao"
                }
            ]
            });

        return this._formPanel;
    },

    validate_departure_period: function (params, cbSuccess) {
        var rest = Ext._create(this.rest, {});
        var mask = Ext._create('Ext.LoadMask', this.getEl(), { msg: 'Processando informações.' });
        var wnd = this;

        mask.show();
        rest._validate_departure_period(
            params,
            {
                scope: this,
                fn: function (rst) {
                    core.invokeCallback((cbSuccess || { fn: Ext.emptyFn }), rst.message);
                    wnd.close();
                }
            },
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: 'Informando',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message
                    });
                }
            },
            {
                fn: function () {
                    mask.hide();
                }
            }
        );
    },

    save: function(close){
        if(this.getParams().afastamento != undefined){
            form = this.getFormPanel().getForm()
            var params = {
                departure: this.getParams().afastamento,
                start_date: form.getValues().data_inicio,
                end_date: form.getValues().data_fim
            };
            var scope = this;
            var func = {
                fn: function() {
                    rh.prorrogacao.Window.superclass.save.call(scope, close);
                }
            };
            this.validate_departure_period(params, func);
        }
    }
});

