    getSituationItemsMenu: function () {
        if (this._situationItems == undefined) {
            this._situationItems = [];
            this._situationItems.push(
                new Ext.form.Checkbox({
                    name: 'active',
                    groupMenu: 'situation',
                    boxLabel: 'ATIVO',
                    checked: true,
                    value: true,
                    scope: this,
                    handler: this.filterSituation
                })
            );
            this._situationItems.push(
                new Ext.form.Checkbox({
                    name: 'finished',
                    groupMenu: 'situation',
                    boxLabel: 'ENCERRADO',
                    checked: true,
                    value: false,
                    scope: this,
                    handler: this.filterSituation
                })
            );
        }
        return this._situationItems;
    },


    getFilterMenu: function () {
        return [
                {
                    name: 'possession_type',
                    groupMenu: '',
                    text: 'Tipo de posse',
                    scope: this,
                    menu: this.getPossessionTypeItemsMenu().concat(
                        [
                            '-',
                            new Ext.menu.CheckItem({
                            text: 'Marcar todos os filtros',
                            name: 'uncheck_possession_type',
                            scope: this,
                            checked: false,
                            hideOnClick: false,
                            handler: function (checked) {
                                this.getPossessionTypeItemsMenu().forEach(
                                    function (item) {
                                        item.setChecked(!checked.checked, true);
                                    }
                                    );
                                this.filterPossessionType(true);
                            }
                        })
                        ]
                    )
            },    
            {
                name: 'situation',
                groupMenu: '',
                text: 'Situação',
                scope: this,
                menu: this.getSituationItemsMenu()
            },
            {
                text: 'Designação de Exercício',
                checked: false,
                hideOnClick: false,
                scope: this,
                handler: this.filterWorkAssignment
            },
            {
                text: 'Responsável',
                checked: false,
                hideOnClick: false,
                scope: this,
                handler: this.filterFullExercice
            },
        ];
    },

    filterWorkAssignment: function () {
        this._WorkAssignment = core.nullValue(this._WorkAssignment, 1);
        if (this._WorkAssignment == 1) {
            this.setFilterProperty('designacao', true, 1);
            this._WorkAssignment = 2;
        }
        else {
            this.removeFilterProperty('designacao');
            this._WorkAssignment = 1;
        }
    },

    filterFullExercice: function () {
        this._FullExercice = core.nullValue(this._FullExercice, 1);
        if (this._FullExercice == 1) {
            this.setFilterProperty('responsible', true, 2);
            this._FullExercice = 2;
        }
        else {
            this.removeFilterProperty('responsible');
            this._FullExercice = 1;
        }
    },

    filterSituation: function () {
        var values = [];
        this.getSituationItemsMenu().forEach(
            function (item) {
                if (item.checked)
                    values.push(item.value);
            }
        );
        this.setFilterProperty('ativo__in', values, 4);
    },


    _setMain: function (pk) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), { msg: 'criando Exercício...' });

        mask.show();
        rest.setMain(
            pk,
            true,
            {
                scope: this,
                fn: function () {
                    this.getStore().reload();
                }
            },
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: 'Adicionando',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                fn: function () {
                    mask.hide();
                }
            }
        );
    },

    getSetMainAction: function (cfg) {
        if (!this._setMainAction) {
            this._setMainAction = Ext._create('Ext.Button', {
                text: 'Marcar como Principal...',
                iconCls: 'icon-core icon-core-reports',
                scope: this,
                handler: function () {
                    if (this.getSelectionModel().getSelected())
                        this._setMain(this.getSelectionModel().getSelected().id);
                    else
                        Ext.Msg.show({
                            title: 'Maracando como Principal',
                            msg: 'Primeiro selecione uma lotação.',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });

                }
            });
        }
        return this._setMainAction;
    },

