    extend: 'rh.movimentacao.pessoal.Window',

    rest: 'rh.movimentacao.possession.Restful',

    width: 650,
    height: 750,

    constructor: function(cfg) {
        this.setLabelProvision(cfg.labelProvision);
        rh.movimentacao.possession.Window.superclass.constructor.call(this, cfg);
        this.is_member = cfg.is_member
        if (this.is_member){
            this.getaid_moving_house_gedoc().enable()
            this.getaid_moving_house_paymente_date().enable()

        }else{
            this.getaid_moving_house_gedoc().disable();
            this.getaid_moving_house_paymente_date().disable();
        
            
        }
    },

    setLabelProvision: function(labelProvision) {
        this.labelProvision = labelProvision;
    },

