/*
 * src: /app/root/rh/static/movimentacao/possession/benefit/reactivated/Window.js
 */
/** autogenerated **/
/**
 *
 **/
Ext._define('rh.movimentacao.possession.benefit.reactivated.Window', {
    extend: 'rh.movimentacao.pessoal.Window',

    rest: 'rh.movimentacao.possession.benefit.reactivated.Restful',

    width: 550,

    constructor: function (cfg) {
        Ext.applyIf(cfg, {
            labelFired: 'Reativar'
        });
        rh.movimentacao.possession.benefit.reactivated.Window.superclass.constructor.call(this, cfg);
    },

    _observe: function () {
        rh.movimentacao.possession.benefit.reactivated.Window.superclass._observe.call(this, {});
        var values = this.getParams();
        if (values != undefined && values.movimentacao_posse != undefined) {
            this.getPossession().setValue(values.movimentacao_posse);
            this.getPossession().setReadOnly(true);
        }
        else
            this.getPossession().setReadOnly(false);
    },

    save: function (close) {
        Ext.Msg.show({
            title: 'Salvando ' + this.title,
            msg: 'Tem certeza que deseja salvar <br> <b>' + this.labelFired + '</b> <br> do(a) servidor(a): <br> <b>' + this.getPossession().getComboField().lastSelectionText + '</b>?',
            scope: this,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            fn: function (btn) {
                if (btn === 'no') return;
                this.benefitReactivated()
            }
        });
    },

    getPanelInformationItems: function (cfg_window) {
        var items = [];
        items.push(this.getPossession(cfg_window, {}));
        items.push(this.getPublicationField(cfg_window, {}));
        items.push({
            allowBlank: false,
            fieldLabel: "Data da Reativação",
            name: "data_exercicio",
            xtype: "datefield"
        });
        items.push({
            allowBlank: false,
            fieldLabel: "Efeito Financeiro - Início",
            name: "financial_effect_date",
            xtype: "datefield"
        });
        items.push({
            xtype: 'checkbox',
            boxLabel: 'Decorrente de decisão judicial',
            allowBlank: true,
            hideLabel: true,
            checked: false,
            name: 'judicial_decision'
        });
        items.push({
            allowBlank: true,
            fieldLabel: "Número do Processo Judicial",
            name: "number_process",
            xtype: "textfield",
            maxLength: 20,
            maxLengthText: 'Esse campo pode tem somente 20 caracteres.'
        });

        return items;
    },

    getPossession: function (cfg_window, cfg) {
        if (!this._posse) {
            cfg = core.nullValue(cfg, {});
            Ext.applyIf(
                cfg,
                {
                    fieldLabel: 'Posse',
                    allowBlank: false,
                    rest: 'rh.movimentacao.possession.AllPossessionsRestful',
                }
            );
            Ext.apply(cfg, { name: 'reactivated_benefit' });
            this._posse = Ext._create('core.fields.AutocompleteField', cfg);
        }
        return this._posse;
    },

    benefitReactivated:function(){
        var params = this.getFormPanel().getForm().getValues()
        var rest = Ext._create('rh.movimentacao.possession.benefit.reactivated.Restful', {});
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});
        mask.show();
        rest.doRequest(
            rest.getRoute('reactivation', false, 'POST', {
                scope: this,
                params,
                callback: function() {
                    mask.hide();
                    mask = undefined;
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);
                    if(rst.success) {
                        this.ownerGrid.getStore().reload();
                        this.destroy();
                    }
                    else
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                },
                failure: function(xhr) {
                    Ext.Msg.show({
                        title: 'Atenção',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Recurso indisponível no momento.'
                    });
                },
            })
        );
    }
});


