Ext._define('rh.employee.trainee.Grid', {
    extend: 'rh.employee.CollaboratorGrid',
    restWindow: 'rh.employee.trainee.Window',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'report', '-', 'search', '->', '-', 'download'],

    getConfigActionsItems: function(cfg){
        var menu = rh.gfp.payroll.PayrollGrid.superclass.getConfigActionsItems.call(this, cfg);
        menu['report'] = {
            text: 'Gerar Relatório',
            iconCls: 'icon-core icon-core-copy',
            menu: [
                {
                    text: 'Ativo(s)',
                    scope: this,
                    handler: function() { this._buildReport(1) }
                },
                {
                    text: 'Inativo(s)',
                    scope: this,
                    handler: function() { this._buildReport(0) }
                }
            ]
        };

        return menu;
    },

    _buildReport: function(ativo){

        engine.mq.Report.request({
            report: '/to/mpe/rh/servidor/collaborators_report',
            waitMessage: 'Gerando relatório...',
            params: {
                outfile: 'relatorio_estagiario',
                report_name: 'Relatório de Estagiário',
                ativo: ativo,
                tipo: 1

            }
        });
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
    	rh.employee.trainee.Grid.superclass.constructor.call(this, cfg);
    }

});

core.RestfulGrid.register(
    'rh.employee.trainee.Restful',
    'rh.employee.trainee.Grid'
);

/*
 * src: /app/root/rh/static/employee/trainee/Manage.js
 */
 Ext._define('rh.employee.trainee.Manage', {
    extend: 'toolkit.widget.TabPanel',

    getEmployeeGrid: function(cfg) {
        if(!this._employeeGrid){
            this._employeeGrid = Ext._create('rh.employee.trainee.Grid', {
                title: 'Estagiário',
                region: 'north',
                border: false,
                split: true,
                minHeight: 350,
                height: 350,
                columnAction: false,
                matriculaFieldBlocked: cfg.matriculaFieldBlocked,
                restWindow: 'rh.employee.trainee.Window',
            });

            this._employeeGrid.setFilterProperty('tipo__in', 'E', 1002, true);

            this._employeeGrid.getSelectionModel().on({
                scope: this,
                rowselect: function(sm, index, record) {
                    this.employee(record.get('pk'));
                },
                rowdeselect: function(sm) {
                    this.employee(null);
                }
            });

            this._employeeGrid.getStore().on({
                scope: this,
                load: function() {
                    this.employee(null);
                }
            });

            this._employeeGrid.getStore().on({
                scope: this,
                load: function() {
                    var selected = (this._employeeGrid.getSelectionModel().getSelected());

                    if(selected)
                        this.employee(selected.get('pk'));
                    else
                        this.employee(null);
                }
            });
        }

        return this._employeeGrid;
    },

    employee: function(value, prevent) {
        prevent = core.nullValue(prevent, false);

        if(value !== undefined) {
            this._employee = value;

            !prevent && this.observeEmployee();
        }

        return this._employee;
    },

    observeEmployee: function() {
        var value = this.employee();
        var grid;

        if(value) {
            grid = this.getDeclarationActivityGrid();
            grid.setParam('servidor', value);
            grid.setFilterProperty('servidor', value, 1001)
            grid.enable();
        }
        else {
            grid = this.getDeclarationActivityGrid();
            grid.setParam('servidor', 0);
            grid.setFilterProperty('servidor', 0, 1001, false);
            grid.getStore().removeAll();
            grid.disable();
        }
    },

    getDeclarationActivityGrid: function() {
        if(!this._declarationActivityGrid){
            this._declarationActivityGrid = Ext._create('rh.declarationactivity.Grid', {
                title: 'Declaração de Atividade',
                region: 'center',
                gridAutoLoad: false,
                minHeight: 300
            });
            this._declarationActivityGrid.setFilterProperty('servidor__tipo', 'E', 1, false);
        }
        return this._declarationActivityGrid;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Gestor de Estagiários',
            }
        );

        Ext.apply(
            cfg,
            {
                border: false,
                layout: 'border',
                items: [
                    this.getEmployeeGrid(cfg),
                    this.getDeclarationActivityGrid()
                ]
            }
        );

        rh.employee.trainee.Manage.superclass.constructor.call(this, cfg);
        this.employee(null);
    }
});


