    markAll: function (grid) {
        var _data = grid.getStore().data;
        var _selected = [];
        for (i = 0; i <= _data.length; i++) {
            _data.items.map(function (item) {
                    _selected.push(item)
            });
        }
        grid.getSelectionModel().clearSelections();
        grid.getSelectionModel().selectRecords(_selected);
    },

