/*
 * src: /app/root/rh/static/person/repeatPersonIncident/Manage.js
 */
/** autogenerated **/
Ext._define('rh.person.repeatPersonIncident.Manage', {
    extend: 'toolkit.widget.TabPanel',

    getRepeatPersonIncidentGrid: function() {
        if(!this._grid) {
            this._grid = Ext._create('rh.person.repeatPersonIncident.Grid', {
                region: 'center',
                title: 'Incidentes de repetição',
                gridAutoLoad: false
            });
        }

        return this._grid;
    },

    getRepeatedPersonGrid: function (cfg) {
        if (!this._repeatedPersonGrid) {
            this._repeatedPersonGrid = Ext._create('rh.person.Grid', {
                title: 'Pessoa com incidente de repetição',
                region: 'north',
                minHeight: 200,
                height: 300,
                split: true,
                configOrderToolBar: ['-', 'search', '->', 'download'],
                gridAutoLoad: false
            });

            this._repeatedPersonGrid.setFilterProperty('repeat_incidents', null, -100);

            this._repeatedPersonGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function (sm) {
                    var selection = sm.getSelections();

                    if (selection.length > 0) {
                        this.repeatedPerson(selection[0]);
                    } else {
                        this.repeatedPerson(null);
                    }
                }
            });
        }

        return this._repeatedPersonGrid;
    },

    repeatedPerson: function (value, prevent) {
        prevent = prevent !== undefined ? prevent : false;

        if (value !== undefined) {
            this._repeatedPerson = value;

            if (!prevent) {
                this.repeatedPersonObserve();
            }
        }

        return this._repeatedPerson;
    },

    repeatedPersonObserve: function () {
        var value = this.repeatedPerson();
        var target = this.getRepeatPersonIncidentGrid();

        if (value) {
            target.enable();
            target.setParam('main_person', value.get('pk'));
            target.setFilterProperty('main_person', value.get('pk'), 100);
        } else {
            target.disable();
            target.setParam('main_person', 0);
            target.setFilterProperty('main_person', 0, 100, null, false);
            target.getStore().removeAll();
        }
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'RepeatPersonIncident'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getRepeatedPersonGrid(cfg),
                    this.getRepeatPersonIncidentGrid(cfg),
                ]
            }
        );

        rh.person.repeatPersonIncident.Manage.superclass.constructor.call(this, cfg);
        this.repeatedPersonObserve();
    }
});


