        ArquivoBancarioConsig: Ext.extend(
            Ext.Window,
            {
                controller: 'GFPGenerateCreditFile',

                getFormPanel: function (cfg) {
                    var items = [];

                    items.push({
                        xtype: 'rest-combofield',
                        rest: 'rh.gfp.payroll.PeriodosFolhaRestful',
                        fieldLabel: 'Período',
                        triggerAction: 'all',
                        lazyRender: true,
                        lazyInit: true,
                        displayField: 'unicode',
                        width: 210,
                        name: 'periodo',
                    });
                    items.push({
                        allowBlank: true,
                        fieldLabel: 'Data de pagamento',
                        name: 'dt_pg',
                        xtype: 'datefield',
                        width: 210,
                        value: (cfg && cfg.params && cfg.params.data_pagamento ? cfg.params.data_pagamento : ''),
                        allowBlank: false
                    });

                    if (!this.formPanel)
                        this.formPanel = new Ext.form.FormPanel({
                            frame: true,
                            items: items,
                        });

                    return this.formPanel;
                },

                build: function () {
                    var params = this.getFormPanel().getForm().getValues()
                    var periodo = params.periodo
                    var dt_pg = params.dt_pg


                    console.log('>>> periodo: '+ periodo)
                    console.log('>>> dt_pg: '+ dt_pg)

                    if(periodo == '' || dt_pg == ''){
                        Ext.Msg.show({
                            title: 'Error',
                            msg: 'Os campos período e Data de pagamento são obrigatórios',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }else{
                        Ext.Ajax.request({
                            url: toolkit.util.Normalize.controller_action(
                                'GFPGerarArquivoConsignado',
                                'gerar_arquivo_bancario_consignado'
                            ),
                            params: {
                                periodo: periodo,
                                dt_pg: dt_pg,
                            },
                            success: function(request) {
                                var obj = Ext.decode(request.responseText);
                                if (obj.success){
                                    Ext.Msg.show({
                                        title: 'Solicitando Relatório',
                                        msg: obj.message,
                                        icon: Ext.Msg.INFO,
                                        buttons: Ext.Msg.OK
                                    });
                                    if (obj.download){
                                        var RemoteObserver = core.RemoteObserver;
                                        var cb = RemoteObserver.on('base-report', {
                                            scope: this,
                                            fn: function (data) {
                                                setTimeout(
                                                    function() {
                                                        toolkit.util.downloadFile({
                                                            url: data.path,
                                                            filename: data.filename,
                                                            approach: 'download',
                                                        });
                                                        RemoteObserver.un('base-report', {scope: this})
                                                    
                                                    },
                                                    1000
                                                );
                                            
                                            }
                                        });            
                                        setTimeout( function() {
                                            Ext.Ajax.request({
                                                url: toolkit.util.Normalize.controller_action(
                                                    this.CLASS_NAME,
                                                    'marker'
                                                ),
                                                params: {
                                                    uuid: obj.uuid
                                                },
                                                success: function() {},
                                                failure: function() {},
                                            });
                                        },
                                        2000);            
                                    }
                                }else{
                                    Ext.Msg.show({
                                        title: 'Error',
                                        msg: obj.message,
                                        icon: Ext.Msg.ERROR,
                                        buttons: Ext.Msg.OK
                                    });
                                }
                            },
                            failure: function() {
                                Ext.Msg.show({
                                    title: this.title,
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                                });
                            },
                            scope: this
                        });
                    }

                    this.destroy();
                },

                constructor: function (cfg) {
                    if (!cfg) cfg = {}

                    Ext.apply(
                        cfg,
                        {
                            title: 'Gerador de arquivo bancário de consignados',
                            closable: true,
                            resizable: false,
                            width: 650,
                            border: false,
                            modal: true,
                            buttons: [
                                {
                                    xtype: 'button',
                                    iconCls: 'icon-siatu icon-siatu-move-down',
                                    text: 'Executar',
                                    width: 85,
                                    height: 25,
                                    scope: this,
                                    handler: function () {
                                        this.build();
                                    }
                                }, {
                                    text: 'Cancelar',
                                    scope: this,
                                    handler: this.destroy
                                }
                            ]
                        }
                    );

                    toolkit.gfp.ArquivoBancario.superclass.constructor.call(this, cfg);
                    this.add(this.getFormPanel(cfg));
                }
            }
        ),

