Ext.ns('toolkit.gfp');

toolkit.gfp.DependentesGrid = Ext.extend(
    Ext.grid.GridPanel,
    {
        constructor: function(cfg, cf){
            this.cf = cf;
            Ext.apply(cfg, {
                title:'Dependentes',
                tbar: this.getToolbar(),
                bbar: this.getPagingToolbar(),
                store: this.getStore(),
                columnLines: true,
                autoExpandColumn: 'autoExpand',
                cm: new Ext.grid.ColumnModel([
                    new Ext.grid.RowNumberer(),
                    {
                        header: 'Nome',
                        dataIndex: 'nome',
                        width: 250,
                    id: 'autoExpand'
                    },
                    {
                        header: 'Tipo Parentesco',
                        dataIndex: 'status',
                        width: 100,
                    },
                    {
                        header: 'Idade',
                        dataIndex: 'idade',
                        width: 80,
                    },
                    {
                        header: 'Data Nascimento',
                        dataIndex: 'dt_nascimento',
                        width:100
                    },
                    {
                        header: 'Data Início',
                        dataIndex: 'data_inicio',
                        width:100
                    }
                    
                    ]),
                'listeners': {
                    'scope': this,
                    'render': function(grid) {
                        new Ext.LoadMask(grid.getEl(), {
                            'store': grid.getStore(),
                            'msg': 'Carregando dados...'
                        });

                        grid.getStore().load({});
                    },
                    dblclick: function() {
                        this.getSelectionModel().getSelected() && this._update()
                    }
                }
            });

            toolkit.gfp.DependentesGrid.superclass.constructor.call(this, cfg);
        },

        getStore: function() {
            if(!this._store)
                this._store = new Ext.data.Store({
                    proxy: new Ext.data.HttpProxy({
                        'url': toolkit.util.Normalize.controller_action('GFPLancador', 'dependentes'),
                        'disableCaching': false
                    }),
                    baseParams:{
                        start:0,
                        limit:5,
                        servidor:this.cf.servidor,
                        date:this.cf.date
                    },
                    reader: new Ext.data.JsonReader({
                        'totalProperty': 'totalRows',
                        'root': 'root',
                        'fields': ['pk', 'nome', 'ir', 'sf', 'ac', 'status', 'idade', 'dt_nascimento','tipo_parentesco','data_inicio']
                    }),
                });
        
            return this._store;
        },

        _create: function() {
            new toolkit.gfp.DependenteForm({
                'action': 'create',
                'params': {
                    'servidor': this.cf.servidor
                }, 
                'callback': {
                    'success': {
                        'scope': this,
                        'handler': function() {
                            this.getStore().reload()
                        }
                    }
                }
            }).show();
        },

        _update: function() {
            var sel = this.getSelectionModel().getSelected();
            if(sel) {
                Ext.Ajax.request({
                    url: toolkit.util.Normalize.controller_action('RHDependente', 'get_list'),
                    params:{
                        'pk':sel.get('pk')
                    },
                    scope: this,
                    'success': function(request) {
                        var obj = Ext.decode(request.responseText);
                        
                        if(obj.success) {
                            new toolkit.gfp.DependenteForm({
                                'action': 'update',
                                'params': {
                                    'pk': sel.get('pk')
                                }, 
                                'values': obj.collection,
                                'callback': {
                                    'success': {
                                        'scope': this,
                                        'handler': function() {
                                            this.getStore().reload()
                                        }
                                    }
                                }
                            }).show();
                        }
                    },
                    'failure': function(request) {
                        Ext.Msg.show({
                            'title': 'Dependente',
                            'message': 'Erro tentando editar o item selecionado.',
                            'icon': Ext.Msg.WARNING,
                            'buttons': Ext.Msg.OK
                        })
                    }
                })
            }
            else Ext.Msg.show({
                'title': 'Dependente',
                'msg': 'Primeiro selecione o item que deseja alterar.',
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK
            });
        },

        _remove: function() {
            var sels = this.getSelectionModel().getSelections();
            var pks = []
            if (sels.length > 0){
                Ext.each(sels, function(record) {
                    pks.push(record.get('pk'))
                });

                Ext.Msg.show({
                    'title': 'Dependente',
                    'msg': 'Tem certeza que deseja remover os itens selecionados.',
                    'icon': Ext.Msg.QUESTION,
                    'buttons': Ext.Msg.YESNO,
                    'scope': this,
                    'fn': function(b) {
                        if(b == 'no') return;

                        Ext.Ajax.request({
                            'scope': this,
                            'url': toolkit.util.Normalize.controller_action('RHDependente', 'remove'),
                            'params': {
                                pk: pks
                            },
                            'success': function(request) {
                                var obj = Ext.decode(request.responseText);
                                if(obj.success) 
                                {
                                    Ext.Msg.alert('Sucesso', 'Dados removidos com sucesso!');
                                    this.getStore().reload();
                                }else{
                                    Ext.Msg.show({
                                        'title': 'Atenção!',
                                        'msg': obj.message,
                                        'icon': Ext.Msg.WARNING,
                                        'buttons': Ext.Msg.OK
                                    });
                                }
                            },
                            'failure': function(request) {
                                this.getStore().reload();
                                Ext.Msg.show({
                                    'title': 'Dependente',
                                    'msg': 'Ocorreram erros removendo os itens selecionados.',
                                    'icon': Ext.Msg.WARNING,
                                    'buttons': Ext.Msg.OK
                                });
                            }
                        })
                    }
                })
            }
            else Ext.Msg.show({
                'title': 'Dependente',
                'msg': 'Primeiro selecione o item que deseja remover.',
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK
            });
        },

        getToolbar: function() {
            if(!this._toolbar)
                this._toolbar = new Ext.Toolbar({
                    'style': 'border-left:none;border-top:none',
                    'items': [
                    {
                        'text': 'Novo',
                        'scope': this,
                        'handler': this._create,
                        'iconCls': 'icon-gep icon-new'
                    },
                    {
                        'text': 'Editar',
                        'scope': this,
                        'handler': this._update,
                        'iconCls': 'icon-gep icon-edit'
                    },
                    {
                        'text': 'Remover',
                        'scope': this,
                        'handler': this._remove,
                        'iconCls': 'icon-gep icon-delete'
                    },
                    '-'
                    ]   
                });
        
            return this._toolbar;
        },

        getPagingToolbar: function() {
            if(!this._pagingToolbar)
                this._pagingToolbar = new Ext.PagingToolbar({
                    'style': 'border-left:none',
                    'store': this.getStore(),
                    'pageSize':5,
                    'displayInfo': true
                });
        
            return this._pagingToolbar;
        }
    }
);

toolkit.gfp.DependenciaGrid = Ext.extend(

    Ext.grid.GridPanel,
    {
        constructor: function(cfg) {
            cfg = (cfg ? cfg : {});
            Ext.apply(cfg, {
                'title':'Dependências',
                'tbar': this.getToolbar(),
                // 'bbar': this.getPagingToolbar(),
                'store': this.getStore(),
                'autoExpandColumn': 'autoExpand',
                'cm': new Ext.grid.ColumnModel([
                    new Ext.grid.RowNumberer(),
                    {
                        header: "Status", 
                        sortable: false, 
                        dataIndex: "status", 
                        key: "status", 
                        // id: "status",
                        width: 40, 
                        renderer: toolkit.util.formatStatus
                    },
                    {
                        'header': 'Tipo',
                        'dataIndex': 'tipo',
                        'id': 'autoExpand'
                    },
                    {
                        'header': 'Data Início',
                        'dataIndex': 'data_inicio',
                        'width': 100
                    },
                    {
                        'header': 'Data Fim',
                        'dataIndex': 'data_fim',
                        'width': 100
                    },
                    {
                        'header': 'Idade Limite',
                        'dataIndex': 'idade_limite',
                        'width': 100
                    },
                    {
                        'header': 'Estudante',
                        'dataIndex': 'estudante',
                        'width': 100
                    },
                    {
                        'header': 'Suspenso',
                        'dataIndex': 'suspenso',
                        'width': 100
                    },
                ]),
                'listeners': {
                    'scope': this,
                    dblclick: function() {
                        this.getSelectionModel().getSelected() && this._update()
                    }
                }
            });

            toolkit.gfp.DependenciaGrid.superclass.constructor.call(this, cfg);

        },

        getStore: function() {
            if(!this._store)
                this._store = new Ext.data.Store({
                    'proxy': new Ext.data.HttpProxy({
                        'url': toolkit.util.Normalize.controller_action('GFPLancador', 'dependencias'),
                        'disableCaching': false,
                        'method': 'GET'
                    }),
                    'reader': new Ext.data.JsonReader({
                        'totalProperty': 'totalRows',
                        'root': 'root',
                        'fields': [
                            'pk',
                            'pk_dependente',
                            'tipo',
                            'data_inicio',
                            'data_fim',
                            'status', 
                            'idade_limite',
                            'estudante',
                            'suspenso',
                            'status' 
                        ]
                    })
                });
        
            return this._store;
        },

        getParams: function(){
            var obj = this.getStore().baseParams;
            return obj;
        },

        _create: function(){
            var pk = this.getParams().pk;
            // console.log(this.getParams());
            new toolkit.gfp.DependenciaForm({
                'action': 'create',
                'params': {
                    'dependencia': pk
                }, 
                'callback': {
                    'success': {
                        'scope': this,
                        'handler': function() {
                            this.getStore().reload()
                        }
                    }
                }
            }).show();
        },

        _update: function() {
            var sel = this.getSelectionModel().getSelected();
            if(sel) {
                Ext.Ajax.request({
                    url: toolkit.util.Normalize.controller_action('RHDependencia', 'get_list'),
                    params:{
                        'pk':sel.get('pk'),
                        'pk_dependente':sel.get('pk_dependente')
                    },
                    scope: this,
                    'success': function(request) {
                        var obj = Ext.decode(request.responseText);
                        
                        if(obj.success) {
                            new toolkit.gfp.DependenciaForm({
                                'action': 'update',
                                'params': {
                                    'pk': sel.get('pk')
                                }, 
                                'values': obj.collection,
                                'callback': {
                                    'success': {
                                        'scope': this,
                                        'handler': function() {
                                            this.getStore().reload()
                                        }
                                    }
                                }
                            }).show();
                        }
                    },
                    'failure': function(request) {
                        Ext.Msg.show({
                            'title': 'Dependente',
                            'message': 'Erro tentando editar o item selecionado.',
                            'icon': Ext.Msg.WARNING,
                            'buttons': Ext.Msg.OK
                        })
                    }
                })
            }
            else Ext.Msg.show({
                'title': 'Dependente',
                'msg': 'Primeiro selecione o item que deseja alterar.',
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK
            });
        },

        _remove: function() {
            var sels = this.getSelectionModel().getSelections();
            var pks = []
            if (sels.length > 0){
                Ext.each(sels, function(record) {
                    pks.push(record.get('pk'))
                });

                Ext.Msg.show({
                    'title': 'Dependências',
                    'msg': 'Tem certeza que deseja remover os itens selecionados.',
                    'icon': Ext.Msg.QUESTION,
                    'buttons': Ext.Msg.YESNO,
                    'scope': this,
                    'fn': function(b) {
                        if(b == 'no') return;

                        Ext.Ajax.request({
                            'scope': this,
                            'url': toolkit.util.Normalize.controller_action('RHDependencia', 'remove'),
                            'params': {
                                pk: pks,
                            },
                            'success': function(request) {
                                var obj = Ext.decode(request.responseText);

                                if(obj.success){
                                    Ext.Msg.alert('Sucesso', 'Dados removidos com sucesso!');
                                    this.getStore().reload();
                                }else{
                                    Ext.Msg.show({
                                        'title': 'Atenção',
                                        'msg': obj.message,
                                        'icon': Ext.Msg.WARNING,
                                        'buttons': Ext.Msg.OK
                                    });

                                }
                            },
                            'failure': function(request) {
                                this.getStore().reload();
                                Ext.Msg.show({
                                    'title': 'Dependências',
                                    'msg': 'Ocorreram erros removendo os itens selecionados.',
                                    'icon': Ext.Msg.WARNING,
                                    'buttons': Ext.Msg.OK
                                });
                            }
                        })
                    }
                })
            } else  Ext.Msg.show({
                'title': 'Dependências',
                'msg': 'Primeiro selecione o item que deseja remover.',
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK
            });
        },

        getToolbar: function() {
            if(!this._toolbar)
                this._toolbar = new Ext.Toolbar({
                    'style': 'border-top:none;border-right:none',
                    'items': [
                    {
                        'text': 'Novo',
                        'iconCls': 'icon-gep icon-new',
                        'scope': this,
                        'handler': this._create
                    },
                    {
                        'text': 'Editar',
                        'scope': this,
                        'handler': this._update,
                        'iconCls': 'icon-gep icon-edit'
                    },
                    {
                        'text': 'Remover',
                        'scope': this,
                        'handler': this._remove,
                        'iconCls': 'icon-gep icon-delete'
                    },
                    '-',
                    ]   
                });
        
            return this._toolbar;
        },

        getPagingToolbar: function() {
            if(!this._pagingToolbar)
                this._pagingToolbar = new Ext.PagingToolbar({
                    'style': 'border-right:none',
                    'store': this.getStore(),
                    'pageSize':5,
                    'displayInfo': true
                });
        
            return this._pagingToolbar;
        }

        
    }
);

