Ext._define('rh.gfp.parameters.RRAEmployeeGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.gfp.parameters.RRAEmployeeWindow',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'search', '->', 'importar' ,'-','download'],


    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Chave', dataIndex: 'chave', width: 90, hidden: true},
                    {header: 'Servidor', dataIndex: 'employee_unicode',id: 'autoExpandColumn'},
                    {header: 'RRA', dataIndex: 'rra_unicode', width: 250},
                    {header: 'Meses', dataIndex: 'months', width: 90},
                    {header: 'Fator', dataIndex: 'factor', width: 90},
                ]
            );

        return this._columnModel;
    },

    getConfigActionsItems: function(cfg) {
        var menu = rh.gfp.parameters.RRAEmployeePayrollTypeGrid.superclass.getConfigActionsItems.call(this, cfg);  

        var items = {
            importar:{
                text: 'Importar',
                iconCls: 'icon-core icon-core-run-ok',
                scope: this,
                handler: function(){this.importaProcesso(cfg)}
            },
        };
        Ext.apply(menu, items);
        
        return menu;
    },


    importaProcesso: function(cfg) {
        console.log()
        const wnd = Ext._create('Ext.Window', {
            title: 'Importar processo',
            width: 500,
            modal: true,
            border: false,
            items: [
                Ext._create('Ext.form.FormPanel', {
                    border: false,
                    frame: true,
                    items: [
                        {
                            fieldLabel: 'Arquivo',
                            xtype: 'ged-fileuploadfield',
                            name: 'arquivo_id',
                            allowBlank: false,
                        }
                        
                    ]
                })
            ],
            buttons: [
                {
                    text: 'Importar',
                    scope: this,
                    handler: function () {
                        var arquivo_id = wnd.getComponent(0).getForm().findField('arquivo_id').getValue();
                        var params = {
                            'arquivo_id':arquivo_id,
                            'processo_id': this.getParams().rra,
                        }
                        this._realizarReq(params);
                        wnd.destroy();
                    }
                },
                {
                    text: 'Fechar',
                    handler: function () { wnd.destroy(); }
                }
            ]
        }).show();
    },

    _realizarReq: function(params){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action('GFPRRAEmployee','importar_processo'),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                var icon = obj.success == true ? Ext.Msg.INFO : Ext.Msg.ERROR;
                Ext.Msg.show({
                    width:"400px",
                    title: this.title,
                    icon: icon,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){}
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

});

