Ext._define('rh.gfp.extrapayment.UpdaterWindow', {
    extend: 'Ext.Window',
    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = new Ext.form.FormPanel({
                border: false,
                frame: true,
                scope: this,
                items: [
                    {
                        xtype: "combo",
                        width: 250,
                        fieldLabel: "Tipo",
                        allowBlank: false,
                        lazyRender: true,
                        hiddenName: "type_value",
                        mode: "local",
                        triggerAction: "all",
                        store: [
                            ['M', "MONETÁRIO"],
                            ['P', "PERCENTUAL"],
                        ],
                        value: 'P',
                    },{
                        xtype: "combo",
                        width: 250,
                        fieldLabel: "Método",
                        allowBlank: false,
                        lazyRender: true,
                        hiddenName: "method_value",
                        mode: "local",
                        triggerAction: "all",
                        store: [
                            ['A', "ADICIONAR"],
                            ['M', "MODIFICAR"],
                        ],
                        value: 'A',
                    },{
                        width: 250,
                        allowBlank: false,
                        fieldLabel: "Valor",
                        name: "value",
                        xtype: "numberfield",
                        value: 0.00
                    },{
                        width: 250,
                        allowBlank: false,
                        fieldLabel: "Início Vigência",
                        name: "start_validity",
                        xtype: "datefield",
                    },
                ],
                buttons: [
                    {
                        text: 'Atualizar',
                        scope: this,
                        handler: this.doSubmit
                    },
                    {
                        text: 'Cancelar',
                        handler: this.destroy
                    }
                ]                

            });
    
        return this._formPanel;
    },

    doSubmit: function(){
        var form = this.getFormPanel().getForm();

        form.waitMsgTarget = this.getEl();
        form.submit({
            url: toolkit.util.Normalize.controller_action('GFPExtraPayment', 'updater'),
            scope: this,
            params: {extra_payment: this.extra_payment.pk},
            waitMsg: 'Aplicando atualização',
            success: function(form, action) {
                var fn = this.success;
                fn && fn.callback.call(fn.scope ? fn.scope : window);
                this.destroy();
            },
            failure: function(form, action) {
                if(action.failureType == 'client')
                    message = 'Erro de comunicação com servidor, tente novamente mais tarde.'
                else
                    message = action.result.message;

                Ext.Msg.show({
                    title: this.title,
                    msg: message,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });

                this.failure && this.failure.callback.call(this.failure.scope ? this.failure.scope : window);
            }
        });
    },

    constructor: function(cfg) {
        cfg = (cfg ? cfg : {});

        Ext.apply(cfg, {
            title: 'Atualizar Período(s)',
            modal: true,
            resizable: false,
            width: 400,
            items: this.getFormPanel()
        });

        rh.gfp.extrapayment.UpdaterWindow.superclass.constructor.call(this, cfg);
    }
});

