Ext._define('rh.gfp.paycheckdifference.PayCheckDifferenceConfigGrid', {
    extend: 'core.RestfulGrid',

    rest: 'rh.gfp.paycheckdifference.PayCheckDifferenceConfigRestful',
    restWindow: 'rh.gfp.paycheckdifference.PayCheckDifferenceConfigWindow',

    showInstallments: function(value, metaData, record, rowIndex, colIndex, store){
        var data = record.data;
        return data.initial_installment == data.final_installment? value: data.initial_installment + ' a ' + data.final_installment;
    },

    showValue: function(value, metaData, record, rowIndex, colIndex, store){
        var data = record.data;
        if(data.typeof == 1){
            return 'R$ '+ toolkit.util.formatCurrency(value);
        }else if(data.typeof == 2){
            return value + '%';
        }else{
            return value + ' sal. mínimo(s)'
        }
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Descricao', dataIndex: 'unicode', width: 120},
                    {header: 'Tipo', dataIndex: 'typeof_display', id: 'autoExpandColumn'},
                    {header: 'Parcelas', dataIndex: 'initial_installment', width: 90, renderer: this.showInstallments},
                    {header: 'Valor', dataIndex: 'value', width: 90, renderer: this.showValue},
                    {header: 'Patronal', dataIndex: 'employer_contribution', width: 90, renderer: this.showValue},
                    {header: 'Diferença', dataIndex: 'difference_unicode', width: 120},
                    {header: 'created at', dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true},
                    {header: 'modified at', dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true},
                    {header: 'modified by', dataIndex: 'modified_by_unicode', width: 90, hidden: true},
                    {header: 'created by', dataIndex: 'created_by_unicode', width: 90, hidden: true},
                ]
            );

        return this._columnModel;
    }
});

