Ext._define('rh.gfp.paycheckdifference.EntriesDifferenceGrid', {
    extend: 'core.RestfulGrid',

    rest: 'rh.gfp.payroll.EntriesRestful',
    restWindow:  'rh.gfp.payroll.EntriesWindow',

    configOrderToolBar: ['edit', 'select', '-', 'search', '-', '->', 'download'],

    hideActions: ['add', 'copy'],

    // updateItem: function(){},
    selectPayment: function(){
        if(!this._windowsEntry){
            this._windowsEntry = new Ext.Window({
                title: 'Selecionar evento',
                modal: true,
                border: false,
                closable: true,
                closeAction: 'hide',
                resizable: false,
                width: 455,
                buttons: [
                    {
                        text: 'Adicionar',
                        scope: this,
                        handler: function(b) {
                            if(this.getEntryField().getValue()!=''){
                                Ext.Ajax.request({
                                    url: toolkit.util.Normalize.controller_action('GFPEntryDifference', 'setDifferenceEntry'),
                                    method: 'POST',
                                    scope: this,
                                    params: {
                                        entry: this.getEntryField().getValue(),
                                        difference: this.getParams().paycheck_difference,
                                    },
                                    success: function(request) {
                                        var obj = Ext.decode(request.responseText);
                                        Ext.Msg.show({
                                           title:'Alerta',
                                           msg: obj.message,
                                           buttons: Ext.Msg.OK,
                                           icon: Ext.MessageBox.WARNING
                                        });
                                        this._windowsEntry.hide();
                                        this.getStore().reload();
                                    },
                                    failure: function(request) {
                                        Ext.Msg.show({
                                           title:'Alerta',
                                           msg: 'Ocorreu um erro na requisição. Comunique ao setor de T.I.',
                                           buttons: Ext.Msg.OK,
                                           icon: Ext.MessageBox.WARNING
                                        });
                                    },
                                    waitMsg: 'Transportando informações...'
                                });
                            }else{
                                Ext.Msg.show({
                                   title:'Alerta',
                                   msg: 'Selecione um folha evento!',
                                   buttons: Ext.Msg.OK,
                                   icon: Ext.MessageBox.WARNING
                                });
                            }
                        }
                    },  
                    {
                        text: 'Cancelar',
                        scope: this,
                        handler: function(b) { 
                            this._windowsEntry.hide();
                        }
                    }
                ],
                listeners: {
                    scope: this,
                    beforehide: function(){
                        this.getEntryField().setValue();
                    },
                    beforeshow: function(){
                        this.setEntryPreFilter();
                    }
                },
                items: [
                {
                    xtype: 'form',
                    frame: true,
                    width: 450,
                    items: [
                        this.getEntryField()
                    ]
                }
                ]
            });

        }

        this._windowsEntry.show();
    },

    setEntryPreFilter: function(){
        this.getEntryField().setPreFilter([
            {property: 'servidor__pk', value: this.employee, stage: 100},
            {property: 'evento__genre_event__pk', value: this.genre_event, stage: 101},
            {property: 'paycheck_difference', value: null, stage: 102}
        ]);
    },

    getEntryField: function() {
        if (!this._entryfield || this._entryfield == null) {
            this._entryfield = Ext._create('core.fields.AutocompleteField', {
                fieldLabel: 'Folha/Evento',
                name: 'folhaevento',
                rest: 'rh.gfp.paycheck.EntriesSimpleRestful',
                allowBlank: false,
                preFilter: [
                    {property: 'servidor__pk', value: this.employee, stage: 100},
                    {property: 'evento__genre_event__pk', value: this.genre_event, stage: 101},
                    {property: 'paycheck_difference', value: null, stage: 102}
                ]
            });
        }

        return this._entryfield;
    },

    getConfigActionsItems: function(cfg){
        rh.gfp.paycheckdifference.EntriesDifferenceGrid.superclass.getConfigActionsItems.call(this, cfg);
        Ext.apply(this._configActionsItems, {
            select:{
                    text: 'Selecionar',
                    iconCls: 'icon-fopag icon-money-pencil',
                    scope: this,
                    handler: this.selectPayment,                
            }
        });
        return this._configActionsItems;
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    // {header: 'Contra-Cheque', dataIndex: 'contracheque_unicode', id: 'autoExpandColumn'},
                    {header: 'Referência', dataIndex: 'reference', width: 150},                    
                    {header: 'Evento', dataIndex: 'unicode', width: 300, id: 'autoExpandColumn'},
                    {header: 'Prazo', dataIndex: 'prazo_desc', width: 90},
                    {header: 'Valor', dataIndex: 'valor', width: 80, renderer: toolkit.util.formatCurrency},
                    {header: 'Patronal (R$)', dataIndex: 'patronal', width: 90, renderer: toolkit.util.formatCurrency},
                ]
            );

        return this._columnModel;
    }
});

