/*
 * src: /app/root/rh/static/gfp/reports/employee/forms/StaticDocuments.js
 */
/*****************************************************************************
*                                                                            *
*                            OUTROS REQUERIMENTOS                            *
*                                                                            *
*****************************************************************************/
Ext._define('rh.gfp.reports.employee.forms.StaticDocuments', {
    extend: 'Ext.form.FormPanel',

    _populateCombo: function (files) {
        this.getDocumentField().getStore().add(files.map(function (file) {
            return Ext._create('Ext.data.Record', {
                title: file.title,
                url: file.url,
                //url: file.url.replace('127.0.0.1', 'athenas.mpto.mp.br'),  // debug
            });
        }));
    },

    _fetchFileUrls: function (cfg) {
        Ext.Ajax.request({
            method: 'GET',
            scope: this,
            url: window.action('services/cms/posts/json'),
            params: {
                start: 0, limit: 1,
                areas__parent__slug: 'intranet',
                areas__slug: 'requerimentos'
            },
            success: function (xhr) {
                var result = Ext.decode(xhr.responseText);

                try {
                    if (!result.list.length || !result.list[0].files.length) {
                        throw new Error('Requisição não retornou resultados');
                    }
                    this._populateCombo(result.list[0].files);
                } catch (e) {
                    this.getDocumentField().setValue('Erro ao carregar a lista');
                    throw e;
                }
            },
            failure: function (xhr) {
                Ext.Msg.show({
                    title: 'Outros requerimentos',
                    msg: 'Recurso indisponível no momento.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                });
            },
        });
    },

    _postConstructor: function (cfg) {
        this._fetchFileUrls(cfg);
    },

    getDocumentField: function (cfg) {
        if (this._documentField) {
            return this._documentField;
        }

        this._documentField = Ext._create('Ext.form.ComboBox', {
            fieldLabel: 'Documento',
            displayField: 'title',
            valueField: 'url',
            editable: false,
            triggerAction: 'all',
            anchor: '99%',
            mode: 'local',
            allowBlank: false,
            emptyText: 'Selecione um item...',
            submitValue: false,

            // OBS: store será populado no método _fetchFileUrls()
            store: Ext._create('Ext.data.ArrayStore', {
                fields: ['title', 'url'],
            }),
        });

        return this._documentField;
    },

    _validateFields: function (cfg) {
        if (this.getForm().isValid()) {
            return;
        }

        Ext.Msg.show({
            title: 'Validando',
            msg: 'Por favor, preencha os campos obrigatórios.',
            icon: Ext.Msg.ERROR,
            buttons: Ext.Msg.OK,
        });

        throw new Error('Por favor, preencha os campos obrigatórios.');
    },

    _generateButtonHandle: function (cfg) {
        this._validateFields(cfg);

        toolkit.util.downloadFile({
            url: this.getDocumentField().getValue(),
            filename: 'requerimento',
        });
    },

    getGenerateButton: function(cfg) {
        if (this._generateButton) {
            return this._generateButton;
        }

        this._generateButton = Ext._create('Ext.Button', {
            text: 'Gerar',
            scope: this,
            iconCls: 'icon-ged icon-ged-application-pdf',
            handler: function () {
                this._generateButtonHandle(cfg);
            },
        });

        return this._generateButton;
    },

    constructor: function (cfg) {
        cfg = cfg || {};

        Ext.apply(cfg, {
            border: false,
            labelWidth: 70,
            items: this.getDocumentField(cfg),
            buttonAlign: 'left',
            buttons: [ this.getGenerateButton(cfg) ],
        });

        rh.gfp
          .reports
          .employee
          .forms
          .StaticDocuments
          .superclass
          .constructor
          .call(this, cfg);

        this._postConstructor(cfg);
    },
});

/*
 * src: /app/root/rh/static/gfp/reports/employee/forms/TimeSheet.js
 */
/*****************************************************************************
*                                                                            *
*                              FOLHA DE PONTO                                *
*                                                                            *
*****************************************************************************/
Ext._define('rh.gfp.reports.employee.forms.TimeSheet', {
    extend: 'rh.gfp.reports.employee.forms.BaseForm',

    mixins: { '1': 'engine.mq.OutputFormatReportMixin' },

    generateReport: function() {  // mixin
        this.validateFields();

        engine.mq.Report.request({
            report: this.reportPath,
            params: this.getParams(),
            el: this.ownerCt.getEl() || this.getEl(),
            waitMessage: 'Processando...',
            showSuccessMsg: false,
        }, this.outputFormat());
    },

    _getYearStore: function (cfg) {
        var years = [];
        var date = new Date();

        date.setMonth(date.getMonth() + 1);

        for (var year = date.getYear() + 1900; year > date.getYear() + 1900 - 5; year--) {
            years.push([year, year])
        }

        return years;
    },

    getYearField: function (cfg) {
        if (this._yearField) {
            return this._yearField;
        }

        this._yearField = Ext._create('Ext.form.ComboBox', {
            fieldLabel: 'Ano',
            hiddenName: 'ano',
            store: this._getYearStore(),
            mode: 'local',
            triggerAction: 'all',
            editable: false,
            anchor: '99%',
            allowBlank: false,
        });

        return this._yearField;
    },

    getMonthField: function (cfg) {
        if (this._monthField) {
            return this._monthField;
        }

        this._monthField = Ext._create('Ext.form.ComboBox', {
            fieldLabel: 'Mês',
            hiddenName: 'mes',
            store: [
                [1, 'JANEIRO'],
                [2, 'FEVEREIRO'],
                [3, 'MARÇO'],
                [4, 'ABRIL'],
                [5, 'MAIO'],
                [6, 'JUNHO'],
                [7, 'JULHO'],
                [8, 'AGOSTO'],
                [9, 'SETEMBRO'],
                [10, 'OUTUBRO'],
                [11, 'NOVEMBRO'],
                [12, 'DEZEMBRO'],
            ],
            mode: 'local',
            triggerAction: 'all',
            editable: false,
            anchor: '99%',
            allowBlank: false,
        });

        return this._monthField;
    },


    /*****************************************************************************
    *                     PROPRIEDADES E MÉTODOS SOBRESCRITOS                    *
    *****************************************************************************/

    reportPath: '/to/mpe/rh/ponto/main',

    onFetchEmployeeSuccess: function (data) {
        if (this.getEmployeeType() === 'E') {
            this.reportPath = '/to/mpe/rh/ponto/main_estagiario';
        }
    },

    getReportName: function (cfg) {
        return 'Folha de Ponto';
    },

    getReportFilename: function (cfg) {
        return `folha-de-ponto-${this.slugify(this.getEmployeeName())}`;
    },

    constructor: function (cfg) {
        cfg = cfg || {};

        Ext.apply(cfg, {
            border: false,
            labelWidth: 33,
            items: [
                this.getEmployeeHiddenField(cfg),
                this.getYearField(cfg),
                this.getMonthField(cfg),
            ],
            buttonAlign: 'left',
            buttons: [ this.getRunReportButton() ],  // mixin
        });

        rh.gfp
          .reports
          .employee
          .forms
          .TimeSheet
          .superclass
          .constructor
          .call(this, cfg);
    },
});

