/*
 * src: /app/root/rh/static/gfp/paycheckdifference/difference_payroll/Manage.js
 */
 Ext._define('rh.gfp.paycheckdifference.difference_payroll.Manage', {
	extend: 'toolkit.widget.TabPanel',

	event: function(value, dispatch){
		dispatch = core.nullValue(dispatch, true);
		if(value !== undefined){
			this._event = value;

			if(dispatch) this.observeEvent();
		}
		else
			return this._event;
	},

	observeEvent: function(){
        var selection = this.getPeriodPayrollGrid().getSelectionModel().getSelections();
		if(this.event() && selection.length == 1){
			this.getDifferenceGrid().enable();
			this.getDifferenceGrid()._event = this.event();
			this.getDifferenceGrid().setParam('period', this.event().pk);
			this.getDifferenceGrid().setFilterProperty('period', this.event().pk, 100);
		}
		else{
			this.getDifferenceGrid().disable();
			this.getDifferenceGrid().getStore().removeAll();
			this.getDifferenceGrid().setFilterProperty('period', 0, 100, false);
		}
    },

	getPeriodPayrollGrid: function(cfg) {
		if(!this._eventGrid){
			this._eventGrid = Ext._create('rh.gfp.paycheckdifference.difference_payroll.Grid', {
				region: 'center',
				extraConf: cfg.folhas,
				gridAutoLoad: true,
				sm: new Ext.grid.RowSelectionModel({singleSelect: false}),
				doubleClickHandler: function(grid) { },
			});

			this._eventGrid.getSelectionModel().on({
				scope: this,
				beforerowselect: function(eventGrid){
					return true
				},
				rowselect: function(eventGrid, index, record){
					this.event(record.data);
				},
				rowdeselect: function(eventGrid, index, record){
					this.event(null);
				},
			});
	
			this._eventGrid.getStore().on({
				scope: this,
				beforeload: function(st, options){
					rec = this._eventGrid.getSelectionModel().getSelected();
					this._eventGrid._lastEvent = rec? rec.data.pk: null;
				},
				load: function(st, records, options){
					if(!records.length)
						this.event(null);
				}
			});
		}

		return this._eventGrid;
	},

	getDifferenceGrid: function(cfg) {
		if(!this._paychecks)
			this._paychecks = Ext._create('rh.gfp.paycheckdifference.difference_payroll.difference.Grid', {
				region: 'south',
				gridAutoLoad: false,
				disabled: true,
				split: true,
				flex: 0.5,
				height: 400,
				hideColumns:[],
                viewConfig: {
                    stripeRows: false,
				},
				extraConf: cfg.folhas
			});

		return this._paychecks;
	},

	constructor: function(cfg) {
		cfg = cfg ? cfg : {};

		Ext.applyIf(
			cfg,
			{
			   title: 'Gerenciamento das Diferenças de Folha'
			}
		);

		Ext.apply(
			cfg,
			{
				layout: 'border',
				defaults: {
					split: true,
				},
				items:[
					this.getPeriodPayrollGrid(cfg),
					this.getDifferenceGrid(cfg),
				]
			}
		);

		rh.gfp.paycheckdifference.difference_payroll.Manage.superclass.constructor.call(this, cfg);
	}
});

/*
 * src: /app/root/rh/static/gfp/paycheckdifference/difference_payroll/Grid.js
 */
 Ext._define('rh.gfp.paycheckdifference.difference_payroll.Grid', {
    extend: 'core.RestfulGrid',

    rest: 'rh.gfp.paycheckdifference.difference_payroll.Restful',

    restWindow: 'rh.gfp.paycheckdifference.difference_payroll.Window',

    hideItemsToolbar: ['edit','search'],
    hideActions: ['remove', 'copy', 'edit'],

    configOrderToolBar: ['add','-','calculate_all', '-', 'calculate_selected'],

    getColumnModel: function(){
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    {header: 'Chave', dataIndex: 'pk', width: 55, hidden: true},
                    {header: 'Período', dataIndex: 'period', 'maxWidth': 200, id: 'autoExpandColumn'},
                    {header: 'Qtd Diferença', dataIndex: 'qtd_diff', width: 130},
                    {header: 'Qtd Dif. Aplicada', dataIndex: 'qtd_diff_applied', width: 130},
                    {header: 'Qtd Dif. Ignorada', dataIndex: 'qtd_diff_ignored', width: 130},
                    {header: 'Último Cálculo', dataIndex: 'calculate_last_date', width: 120},
                ]
            );

        return this._columnModel;
    },

    _calculatePeriod: function(period_id){
        xt.Msg.show({
            msg: 'Tem certeza que deseja calcular o período selecionado?',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                Ext.Ajax.request({
                    url: toolkit.util.Normalize.controller_action('GFPPeriodPayroll','calculate_period'),
                    params: { period_id: period_id },
                    success: function(request) {
                        var obj = Ext.decode(request.responseText);
                        Ext.Msg.show({
                            width:"400px",
                            title: this.title,
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK,
                            msg: obj.message
                        });
                        this.getStore().reload();
                    },
                    failure: function() {
                        Ext.Msg.show({
                            title: this.title,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                        });
                    },
                    scope: this
                });
            }
        })
    },

    _calculateSelectedPeriods: function(){
        var selecteds = this.getSelectionModel().getSelections().map(function(a){ return a.id; });

        if(selecteds.length == 0){
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Escolha pelo menos um período para ser calculado.'
            });
        }else if(selecteds.length > 6){
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Escolha no máximo 6 períodos para serem calculados.'
            });
        }else{
            Ext.Msg.show({
                msg: 'Tem certeza que deseja calcular os períodos selecionados?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function (b) {
                    if (b == 'no') return;
    
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('GFPPeriodPayroll','calculate_selected_periods'),
                        params: { periods_ids: selecteds },
                        success: function(request) {
                            var obj = Ext.decode(request.responseText);
                            Ext.Msg.show({
                                width:"400px",
                                title: this.title,
                                icon: Ext.Msg.INFO,
                                buttons: Ext.Msg.OK,
                                msg: obj.message
                            });
                            this.getStore().reload();
                        },
                        failure: function() {
                            Ext.Msg.show({
                                title: this.title,
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                            });
                        },
                        scope: this
                    });
                }
            });
        }
    },

    _calculateAllPeriods: function(){
        xt.Msg.show({
            msg: 'Tem certeza que deseja calcular todos os períodos?',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                Ext.Ajax.request({
                    url: toolkit.util.Normalize.controller_action('GFPPeriodPayroll','calculate_all_periods'),
                    success: function(request) {
                        var obj = Ext.decode(request.responseText);
                        Ext.Msg.show({
                            width:"400px",
                            title: this.title,
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK,
                            msg: obj.message
                        });
                        this.getStore().reload();
                    },
                    failure: function() {
                        Ext.Msg.show({
                            title: this.title,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                        });
                    },
                    scope: this
                });
            }
        });
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-core icon-core-run',
                tooltip: 'Calcular',
                scope: this,
                handler: function(action, index){ this._calculatePeriod(action._store.getAt(index).data.pk) },
            },
        ];
    },

    getConfigActionsItems: function(cfg){
        if(!this._configActionsItems){
            rh.gfp.paycheckdifference.difference_payroll.Grid.superclass.getConfigActionsItems.call(this, cfg);
            var _menu = {
                calculate_all:{
                    text: 'Calcular Todos',
                    iconCls: 'icon-fopag icon-arrow-repeat',
                    style: {
                        'color': '#FF0000',
                        'font-weight': 'bold'
                    },
                    tooltip: 'Calcular Todos',
                    disabled: false,
                    scope: this,
                    handler: function(){ this._calculateAllPeriods() },
                },
                calculate_selected:{
                    text: 'Calcular Selecionados',
                    iconCls: 'icon-fopag icon-task-select',
                    style: {
                        'color': '#FF0000',
                        'font-weight': 'bold'
                    },
                    tooltip: 'Calcular Selecionados',
                    disabled: false,
                    scope: this,
                    handler: function(){ this._calculateSelectedPeriods() },
                },
            };
            Ext.apply(this._configActionsItems, _menu);

        }
        return this._configActionsItems;
    },

});

