    _finish: function () {
        if (!this.getSelectionModel().getSelected()) {
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: "Selecione um item.",
            });
        } else {
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: "Finalizar Conferência selecionada?",
                scope: this,

                fn: function (btn) {
                    if (btn == "no") return;
                    var sel = this.getSelectionModel().getSelected();
                    var params = {
                        actionCustom: "finish",
                        pk: sel.id,
                    };

                    this._process(params);
                },
            });
        }
    },

    defaultClickFunction: function() {
       
    },

