Ext._define('rh.gfp.dirf.DialectGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.gfp.dirf.DialectWindow',
    rest: 'rh.gfp.dirf.DialectRestful',

    configOrderToolBar: ['add', 'edit', '-', 'dirf', '-', '->', 'download'],

    hideActions: ['edit', ],

    actionColumnWidth: 90,

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Ano referência', dataIndex: 'reference_year', width: 100},
                    {header: 'Ano calendário', dataIndex: 'calendar_year', width: 100},
                    {header: 'Descricao', dataIndex: 'unicode', width: 250, hidden: true},
                    {header: 'Nome', dataIndex: 'nome', id: 'autoExpandColumn'},
                    {header: 'Último recibo', dataIndex: 'last_receipt', width: 250},
                    {header: 'Layout ID', dataIndex: 'identificador_layout', width: 90},
                    {header: 'Processado em', dataIndex: 'last_processed_summary', width: 120, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                ]
            );

        return this._columnModel;
    },

    _downloadFile: function(dialect) {
        var selection = this.getSelectionModel().getSelected();

        if(dialect && dialect.permalink)
            open(dialect.permalink, "_self");
        else
            Ext.Msg.show({
                title: 'Fazendo download',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Ainda não foi gerado a arquivo para essa configuração'
            });
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-fopag icon-compile',
                tooltip: 'Processar DIRF',
                scope: this,
                handler: function(action, index) {
                    if(!this.getSelectionModel().isSelected(index))
                        this.getSelectionModel().selectRow(index);
                    this.processDIRF(action._store.getAt(index).data);
                }
            },
            {
                iconCls: 'icon-fopag icon-notebook-plus',
                tooltip: 'Baixar arquivo da DIRF',
                scope: this,
                handler: function(action, index) {
                    if(!this.getSelectionModel().isSelected(index))
                        this.getSelectionModel().selectRow(index);
                    this._downloadFile(action._store.getAt(index).data);
                }
            },
        ];
    },

    processDIRF: function(dialect, onlyGenerate) {
        if(dialect){
            Ext.Msg.show({
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: 'Tem certeza que deseja processar a DIRF?',
                scope: this,
                fn: function(b) {
                    if(b == 'no') return;
                    var rMask = new Ext.LoadMask(this.ownerCt.getEl(), {msg: "Enviando solicitação...!"});
                    rMask.show();
                    console.debug(dialect);
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('DIRFDialect', (onlyGenerate? 'generate': 'summarize')),
                        params: {
                            dialect: dialect.pk,
                        },
                        success: function(request) {
                            var obj = Ext.decode(request.responseText);
                            rMask.hide();
                            if(!obj.success){
                                Ext.Msg.show({
                                    icon: Ext.Msg.ERROR,
                                    msg: obj.message,
                                    buttons: Ext.Msg.OK
                                });
                            }
                            // console.debug(obj);
                        },
                        failure: function(request) {
                            console.debug(request);
                            rMask.hide();
                            alert('Erro processando a DIRF.')
                        },
                        scope: this
                    });
                }
            });
        }else
            Ext.Msg.show({
                'title': 'Processamento da DIRF',
                'msg': 'Selecione uma configuração primeiro!',
                'buttons': Ext.Msg.OK,
                'icon': Ext.Msg.WARN
            });
    },

    buildOverview: function(){

        var s = this.getStore();
        var selection = this.getSelectionModel().getSelected();

        if(selection){

            engine.mq.Report.request({
                report: '/to/mpe/gfp/dirf',
                el: this.getEl(),
                waitMessage: 'Gerando relatório...',
                params: {

                    outfile: 'dirf-configuracoes-' + selection.get('calendar_year'),
                    report_name: 'DIRF Configurações',
                    dialect: selection.get('pk'),
                }

            });

        }else Ext.Msg.show({
            msg: obj.message,
            icon: Ext.Msg.ERROR,
            buttons: Ext.Msg.OK
        })
    },

    getConfigActionsItems: function(cfg){
        if(!this._configActionsItems){
            rh.gfp.dirf.DialectGrid.superclass.getConfigActionsItems.call(this, cfg);
            // console.debug(menu);
            var _menu = {
                dirf:{
                    text: 'Processamento da DIRF',
                    iconCls: 'icon-fopag icon-stamp-arrow',
                    scope: this,
                    menu: [
                        {
                            text: 'Processar',
                            iconCls: 'icon-fopag icon-stamp-arrow',
                            scope: this,
                            handler: function(){
                                var selection = this.getSelectionModel().getSelected();
                                this.processDIRF(selection?selection.data:null);
                            }
                        },
                        {
                            text: 'Gerar arquivo e declarações',
                            iconCls: 'icon-fopag icon-compile',
                            scope: this,
                            handler: function(){
                                var selection = this.getSelectionModel().getSelected();
                                this.processDIRF(selection?selection.data:null, true);
                            }
                        },
                        {
                            text: 'Relatório de configuração',
                            iconCls: 'icon-core icon-core-reports',
                            scope: this,
                            handler: this.buildOverview
                        },

                    ]
                },
            };
            Ext.apply(this._configActionsItems, _menu);

        }
        return this._configActionsItems;
    },
});

