Ext._define('rh.gfp.provisionplan.ProvisionManagerGrid', {
    extend: 'core.RestfulGrid',

    // restWindow: 'rh.gfp.provisionplan.ProvisionManagerWindow',
    rest: 'rh.gfp.provisionplan.ProvisionManagerRestful',

    hideActions: ['copy', 'edit', 'remove'],

    configOrderToolBar: ['provision', '-' ,'provisiontype', '-', 'search',  '->', 'generate_report', 'download'],

    rendererReference: function(value, metaData, record, rowIndex, colIndex, store){
        return record.data['reference_month'] + ' / ' + record.data['reference_year']
    },

    getTotalValue: function(value, metaData, record, rowIndex, colIndex, store){
        record.data['total_value'] = record.data['total_paid_value'] + record.data['total_provisioned_value'] + record.data['total_previous_balance_value'] + record.data['total_manual_balance_value'];
        return toolkit.util.formatCurrency(record.data['total_value']);
    },

    getTotalEmployer: function(value, metaData, record, rowIndex, colIndex, store){
        record.data['total_employer'] = record.data['total_paid_employer'] + record.data['total_provisioned_employer'] + record.data['total_previous_balance_employer'] + record.data['total_manual_balance_employer'];
        return toolkit.util.formatCurrency(record.data['total_employer']);
    },

    getTotal: function(value, metaData, record, rowIndex, colIndex, store){
        return toolkit.util.formatCurrency(record.data['total_value'] + record.data['total_employer']);
    },

    getConfigActionsItems: function(cfg){
        var menu = rh.gfp.provisionplan.ProvisionManagerGrid.superclass.getConfigActionsItems.call(this, cfg);
        menu['provision'] = {
            text: 'Gestor de Provisões',
            iconCls: 'icon-core icon-core-copy',
            menu: [
                {
                    text: 'Gerar Provisão',
                    handler: this.callWindowProvisionGenerator,
                    scope: this,
                    iconCls: 'icon-core icon-core-run',
                },
                {
                    text: 'Recalcular Provisão',
                    handler: this.recalculateProvision,
                    scope: this,
                    iconCls: 'icon-fopag icon-arrow-repeat',
                },
                {
                    text: 'Mudar status',
                    menu: [
                        {
                            text: 'Em produção',
                            scope: this,
                            iconCls: '',
                            handler: function() { this.changeStatus(1) }
                        },
                        {
                            text: 'Em analise',
                            scope: this,
                            iconCls: '',
                            handler: function() { this.changeStatus(2) }
                        },
                        {
                            text: 'Processado',
                            scope: this,
                            iconCls: 'icon-fopag icon-stamp-arrow',
                            handler: function() { this.changeStatus(4) }
                        },
                        {
                            text: 'Fechado',
                            scope: this,
                            iconCls: 'icon-fopag icon-closed-padlock',
                            handler: function() { this.changeStatus(3) }
                        }
                    ]
                },
                
            ]
        };

        menu['provisiontype'] = {
                text: 'Provisões/Tipo',
                iconCls: 'icon-rh icon-core-indirect',
                scope: this,
                handler: this.provisionTypeWindow
        };

        menu['generate_report'] = {
            text: 'Gerar Relatório',
            iconCls: 'icon-rh icon-core-documents',
            scope: this,
            handler: this.generateReport
        };



        return menu;
    },

    generateReport: function(){
        var selected = this.getSelectionModel().getSelected();
        
        if(selected){
            var regime = selected.get('pension_system_display');
            var plan = selected.get('provision_plan_unicode');
            var referencia = selected.get('reference_month') + '-' + selected.get('reference_year');
            engine.mq.Report.request({
                report: '/to/mpe/financeiro/ProvisionReport',
                waitMessage: 'Gerando relatório...',
                params: {
                    outfile: 'provisionamento_' + plan + '_' + regime + '_' + referencia,
                    report_name: 'Relatório de Provisionamento: ' + plan + ' - ' + regime + ' - ' + referencia,
                    reference_month: selected.get('reference_month'),
                    reference_year: selected.get('reference_year'),
                    type_provision: selected.get('type_provision'),
                    regime_previdenciario: selected.get('pension_system')

                }
            });
        }
        else Ext.Msg.show({
            'title': this.title,
            'icon': Ext.Msg.ERROR,
            'buttons': Ext.Msg.OK,
            'msg': 'Primeiro selecione uma provisão.'
        });
    },

    provisionTypeWindow: function(){
        new Ext.Window({
             id: 'provisiontype',
             layout: 'fit',
             title: 'Provisões/Tipo',
             autoScroll: false,
             modal: true,
             width:800,
             height: 500,
             items: [ new rh.gfp.provisionplan.ProvisionPlanGrid({})],
             listeners: {}
         }).show();

    },

    recalculateProvision: function()  {
        var selection = this.getSelectionModel().getSelected();
        if(selection) {
            Ext.Msg.show({
                scope: this,
                title: 'Recalcular Provisão?',
                msg: 'Tem certeza que deseja recalcular a provisão selecionada?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                fn: function(button) {
                    if(button == 'no') return;

                    Ext.Ajax.request({
                        scope: this,
                        url: toolkit.util.Normalize.controller_action('PCProvisionManager', 'recalculateProvision'),
                        params: { provision_pk: selection.get('pk')},
                        success: function(request) {
                            this.getStore().reload()
                        },
                        failure: function(request) {
                            Ext.Msg.show({
                                title: 'Justificativa',
                                msg: 'Ocorreram erros ao recalcular provisão.',
                                icon: Ext.Msg.WARNING,
                                buttons: Ext.Msg.OK
                            });
                        }
                    });
                }
            })
        }
        else alert('Primeiro selecione um item para recalcular');
    },

    togglePlan: function(tipo) {
        if(!this._filterPlan)
            this._filterPlan = [1, 2];

        if(this._filterPlan.indexOf(tipo) >= 0)
            this._filterPlan.remove(tipo);
        else
            this._filterPlan.push(tipo);

        this.setFilterProperty('provision_plan__type_provision__in', this._filterPlan, 1000);
    },

    togglePensionSystem: function(tipo) {
        if(!this._filterPension)
            this._filterPension = [1, 2, 3];

        if(this._filterPension.indexOf(tipo) >= 0)
            this._filterPension.remove(tipo);
        else
            this._filterPension.push(tipo);

        this.setFilterProperty('pension_system__in', this._filterPension, 1001);
    },

    getFilterMenu: function() {
        return [
        {
            text: 'Por Plano',
            menu: [
                {
                    text: 'FÉRIAS',
                    checked: true,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.togglePlan(1); }
                },
                {
                    text: '13° SALÁRIO',
                    checked: true,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.togglePlan(2); }
                }
            ]
        },
        '-',
        {
            text: 'Por Regime',
            menu: [
                {
                    text: 'RGPS',
                    checked: true,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.togglePensionSystem(1); }
                },
                {
                    text: 'RPPS',
                    checked: true,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.togglePensionSystem(2); }
                },
                {
                    text: 'MILITAR',
                    checked: true,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.togglePensionSystem(3); }
                }
            ]
        },
        '-',
        {
            text: 'por Ano',
            scope: this,
            handler: this.filterYear
        }
        ];
        
            
    },

    filterYear: function() {
        var filter = this.getFilter();
        var reference_year;

        var form = Ext._create('Ext.form.FormPanel', {
            frame: true,
            items: [
                {
                    xtype: 'textfield',
                    fieldLabel: 'Ano',
                    name: 'reference_year',
                    value: reference_year
                },
            ]
        });

        var wnd = Ext._create('Ext.Window', {
            title: 'Filtro por ano',
            modal: true,
            resizable: false,
            border: false,
            width: 300,
            items: [form],
            buttons: [
                {
                    text: 'Aplicar',
                    scope: this,
                    handler: function() {
                        var data = form.getForm().getValues();
                        this.removeFilterProperty('reference_year', 1012, false);
                        this.removeFilterProperty('reference_year', 1013, false);
                        if (data.reference_year != ''){

                            this.setFilterProperty('reference_year', data.reference_year, 1012, false);
                        }
                        this.getStore().reload();
                        wnd.close();
                    }
                },
                {
                    text: 'Limpar',
                    scope: this,
                    handler: function() {
                        this.removeFilterProperty('reference_year', 1012);
                        this.getStore().reload();
                        wnd.close();
                    }
                },
                {
                    text: 'Cancelar',
                    handler: function() {
                        wnd.close();
                    }
                }
            ]
        });

        wnd.show();
    },

    changeStatus: function(status) {
        var s = this.getStore();
        var selection = this.getSelectionModel().getSelected();

        if(selection) {
            Ext.Msg.show({
                msg: 'Tem certeza que deseja mudar o status da provisão?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function(b) {
                    if(b == 'no') return;

                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('PCProvisionManager', 'update_status_provision'),
                        params: {
                            pk: selection.get('pk'),
                            status: status
                        },
                        success: function(request) {
                            var obj = Ext.decode(request.responseText);

                            if(obj.success) s.reload();
                            else
                                Ext.Msg.show({
                                    msg: obj.message,
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK
                                })
                        },
                        failure: function() {
                                Ext.Msg.show({
                                    msg: 'Ocorreu um erro tentando processar sua requisição, tente novamente mais tarde.',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK
                                })
                        },
                        scope: this
                    })
                }
            })
        }
        else Ext.Msg.show({
            msg: 'Primeiro selecione uma provisão.',
            icon: Ext.Msg.ERROR,
            scope: this,
            buttons: Ext.Msg.OK
        });
    },

    callWindowProvisionGenerator: function() {
        new rh.gfp.provisionplan.WindowProvisionGenerator({}).show();
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', renderer: toolkit.util.rendererIconGrid, width: 30},
                    {header: 'Referência', dataIndex: 'reference', renderer:this.rendererReference, width: 90},
                    {header: 'Plano de Provisão', dataIndex: 'provision_plan_unicode', id: 'autoExpandColumn'},
                    {header: 'Regime previdenciário', dataIndex: 'pension_system_display', width: 90},
                    {header: 'Valor liquidado', dataIndex: 'total_paid_value', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Valor aprovisionado', dataIndex: 'total_provisioned_value', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Saldo anterior valor', dataIndex: 'total_previous_balance_value', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Balanço valor', dataIndex: 'total_manual_balance_value', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Saldo valor', dataIndex: 'total_value', renderer: {fn: this.getTotalValue, scope: this}, width: 90},
                    {header: 'Patronal liquidado', dataIndex: 'total_paid_employer', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Patronal aprovisionado', dataIndex: 'total_provisioned_employer', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Saldo anterior patronal', dataIndex: 'total_previous_balance_employer', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Balanço patronal', dataIndex: 'total_manual_balance_employer', renderer: toolkit.util.formatCurrency, width: 90},
                    {header: 'Saldo patronal', dataIndex: 'total_employer', renderer: {fn: this.getTotalEmployer, scope: this}, width: 90},
                    {header: 'Total', dataIndex: 'total', renderer: {fn: this.getTotal, scope: this}, width: 90},
                ]
            );

        return this._columnModel;
    }
});

