Ext._define('rh.afastamento.recesso.BatchRecessWindow', {
    extend: 'Ext.Window',
    // rest: 'rh.afastamento.recesso.Restful',

    width: 450,

    height: 200,

    getFormPanel: function (cfg) {
        if (!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    {
                        xtype: 'combo',
                        fieldLabel: 'Tipo de Servidor',
                        allowBlank: false,
                        lazyRender: true,
                        hiddenName: 'employee_type',
                        mode: 'local',
                        triggerAction: 'all',
                        store: [
                            ['I', 'INDEFINIDO'],
                            ['E', 'ESTAGIÁRIO'],
                            ['M', 'MEMBRO DO MINISTÉRIO PÚBLICO'],
                            ['P', 'MILITAR'],
                            ['S', 'SERVIDOR'],
                            ['T', 'TERCEIRIZADO'],
                            ['V', 'VOLUNTÁRIO'],
                            ['A', 'JOVEM CIDADÃO - APRENDIZ'],
                        ],
                        value: 'S',
                        name: 'employee_type',
                        width: 200
                    },
                    {
                        xtype: 'datefield',
                        allowBlank: true,
                        fieldLabel: 'Inicio recesso',
                        name: 'start_date',
                        width: 200
                    },
                    {
                        xtype: 'datefield',
                        allowBlank: true,
                        fieldLabel: 'Fim recesso',
                        name: 'end_date',
                        width: 200
                    },
                    {
                        xtype: 'core-fileuploadfield',
                        fieldLabel: 'Arquivo CSV',
                        width: 280,
                        labelAlign: 'top',
                        name: 'registry_file'
                    }
                ]

            });
        return this._formPanel;
    },

    save: function () {
        var form = this.getFormPanel().getForm().getValues();
        if (form)
            if ((form.start_date === '') || (form.end_date === '') || (form.employee_type === '') || form.registry_file === '') {
                Ext.Msg.show({
                    title: 'Aviso',
                    msg: 'Informe todos os campos do formulário.',
                    buttons: Ext.Msg.OK,
                    icon: Ext.MessageBox.WARNING
                });
            } else {
                var mask = new Ext.LoadMask(this.getEl(), {
                    'msg': 'Enviando informações...'
                });
                mask.show();
                Ext.Ajax.request({
                    scope: this,
                    url: toolkit.util.Normalize.controller_action(
                        'AFARecessoRestful',
                        'create_batch_recess'
                    ),
                    method: 'POST',
                    params: {
                        start_date: form.start_date,
                        end_date: form.end_date,
                        registry_file: form.registry_file,
                        employee_type: form.employee_type
                    },
                    success: function (request) {
                        mask.hide();
                        this.values = Ext.decode(request.responseText);
                        if (this.values.success == false)
                            alert(this.values.message);
                        else {
                            alert(this.values.message);
                            args.callback.load();
                        }
                    },
                    failure: function () {
                        mask.hide();
                        this.values = Ext.decode(request.responseText);
                        if (this.values.success == false) alert(this.values.message);
                    },
                    waitMsg: "salvando..."
                });

            }
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Criação de recesso em lote',
                closable: true,
            }
        );
        Ext.apply(
            cfg,
            {
                border: false,
                layout: 'fit',
                items: [
                    this.getFormPanel(cfg)
                ],
                buttons: [
                    {
                        text: 'Enviar',
                        scope: this,
                        handler: this.save
                    },
                    {
                        text: 'Cancelar',
                        scope: this,
                        handler: this.destroy
                    }
                ]
            }
        );

        rh.afastamento.recesso.BatchRecessWindow.superclass.constructor.call(this, cfg);
    }
});
