Ext.ns('toolkit.gep');

toolkit.gep.comissaoForm = Ext.extend(
    Ext.Window,
    {
        constructor: function(cfg) {
            cfg = (cfg ? cfg : {});
            Ext.apply(cfg, {
                title: 'Comissão de Avaliação',
                closable: true,
                resizable: true,
                modal: true,
                width: '400',
                border: false,
                buttons: [
                {
                    text: 'Salvar',
                    scope: this,
                    handler: this.save
                },
                {
                    text: 'Cancelar',
                    scope: this,
                    handler: this.destroy
                }
                ]   
            });

            toolkit.gep.comissaoForm.superclass.constructor.call(this, cfg);
            this.add(this.getFormPanel());
            if(this.values) this.getFormPanel().getForm().setValues(this.values);
            // console.log(this.values)
        },

        getFormPanel: function() {
            if(!this._formPanel)
                this._formPanel = new Ext.form.FormPanel({
                    frame: true,
                    labelAlign: 'top',
                    items: [
                        {
                            'displayField': 'description', 
                            'name':'configuracao',
                            'fieldLabel': 'Comissão Anterior', 
                            'allowBlank': true, 
                            'hiddenName': 'comissao_anterior', 
                            'valueField': 'pk', 
                            'triggerAction': 'all', 
                            'queryAction': 'query', 
                            'hideTrigger': true, 
                            'queryParam': 'keyword', 
                            'crudController': 'GEPComissaoAvaliadora', 
                            'xtype': 'autocompletefield',
                            'width': 450
                        },
                        {
                            'displayField': 'description', 
                            'name':'configuracao',
                            'fieldLabel': 'Publicação', 
                            'allowBlank': false, 
                            'hiddenName': 'publicacao', 
                            'valueField': 'pk', 
                            'triggerAction': 'all', 
                            'queryAction': 'query', 
                            'hideTrigger': true, 
                            'queryParam': 'keyword', 
                            'crudController': 'RHPublicacao', 
                            'xtype': 'autocompletefield',
                            'width': 450
                        },
                        {
                            xtype:'fieldset',
                            title:'Vigência',
                            width:395,
                            layout:'hbox',
                            items:[
                                {
                                    xtype:'panel',
                                    layout:'form',
                                    labelAlign:'top',
                                    flex:'1',
                                    width:150,
                                    items:[
                                        {
                                            allowBlank: false,
                                            xtype: 'datefield',
                                            name: 'data_inicio',
                                            fieldLabel: 'Data Início',
                                        }
                                    ]
                                },
                                {
                                    xtype:'panel',
                                    layout:'form',
                                    labelAlign:'top',
                                    flex:'1',
                                    width:150,
                                    items:[
                                        {
                                            allowBlank: true,
                                            xtype: 'datefield',
                                            name: 'data_fim',
                                            fieldLabel: 'Data Fim',
                                        }
                                    ]
                                }
                            ]
                        },
                    ]
                });
        
            return this._formPanel;
        },

        getParams: function() {
            return this.params;
        },

        save: function() {
            var form = this.getFormPanel().getForm();
            //console.log(this.action);
            form.waitMsgTarget = this.getEl();
            form.submit({
                url: toolkit.util.Normalize.controller_action('GEPComissaoAvaliadora', this.action),
                params: this.getParams(),
                scope: this,
                success: function(form, action) {
                    // this.getStore().reload();
                    if(this.callback && this.callback.success)
                        this.callback.success.handler.call(this.callback.success.scope ? this.callback.success.scope : window);
                    Ext.Msg.alert('Sucesso', 'Dados salvos com sucesso!');
                    this.destroy()
                },
                failure: function(form, action) {
                    console.debug(action);

                    var message = ''
                    if(action.failureType == 'connect')
                        message = 'Não consegui acessar o recurso no servidor.'
                    else
                        message = action.result.message

                    Ext.Msg.show({
                        title: 'Comissão',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });

                    if(this.callback && this.callback.failure)
                        this.callback.failure.handler.call(this.callback.failure.scope ? this.callback.failure.scope : window);
                },
                waitMsg: 'Salvando dados...'
            })
        }
        
    }
    );
