    getManifestacaoExternaWindow: function(){
        var selected = this.getSelectionModel().getSelected();
        // console.log(selected);
        if (selected){
            var rest = Ext._create('estagio.avaliado.EstagioAvaliacaoRestful', {});
            var mask = new Ext.LoadMask(this.getEl(), {msg: 'Carregando dados...'});
            mask.show();
            rest.doRequest(
                rest.getRoute('get_list_questionario', [selected.data.questionario_manifestacao_id, selected.data.pk], 'POST', {
                    params:{periodo: selected.data.etapa_atual},
                    scope: this,
                    callback: function() {
                        mask.hide();
                        mask = undefined;
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);
                        if(rst.success) {
                            var montaQuestionario = new toolkit.questionario.MontaQuestionario({
                                'title': selected.data.questionario_manifestacao,
                                'action': 'create',
                                'values':rst.collection,
                                'callback': {
                                    'success': {
                                        'scope': this,
                                        'handler': function() { 
                                            Ext.Ajax.request({
                                                url: toolkit.util.Normalize.controller_action('GepEstagioAvaliacao','save_manifestacao_estagio_externa'),
                                                scope:this,
                                                params:{
                                                    pk_gestor_estagio: selected.data.pk,
                                                    pk_questionario_resposta:montaQuestionario.retorno,
                                                },
                                                'success': function(request) {
                                                    var obj = Ext.decode(request.responseText);
                                                    Ext.Msg.show({
                                                        'title': 'Estágio Probatório',
                                                        'icon': Ext.Msg.INFO,
                                                        'buttons': Ext.Msg.OK,
                                                        'msg': obj.message
                                                    });
                                                    this.getStore().reload();
                                                },
                                                failure: function(response, opts) {
                                                    console.log(opts.result.message)
                                                    Ext.Msg.show({
                                                        'title': 'Atenção!',
                                                        'msg': 'Erro ao salvar os dados',
                                                        'icon': Ext.Msg.WARNING,
                                                        'buttons': Ext.Msg.OK
                                                    });
                                                }
                                            });
                                        }
                                    }
                                }
                            }, rst.collection, selected.data.questionario_manifestacao);

                            montaQuestionario.show();
                        }
                        else
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function(xhr) {
                        console.log('>>> ERRO');
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponível no momento.'
                        });
                    },
                })
            );

        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um servidor'
            });
        }

    },

