/** autogenerated **/
/**
 *
 **/
Ext._define('rh.registration.forminformation.admin.Grid', {
    extend: 'rh.registration.forminformation.Grid',

    restWindow: 'rh.registration.forminformation.admin.Window',
    configOrderToolBar: ['edit', '-', 'receive_information', '-', 'activeAction', '-', 'report_form', '-', 'search'],

    getConfigActionsItems: function(cfg){
        var menu = rh.registration.forminformation.admin.Grid.superclass.getConfigActionsItems.call(this, cfg);
        menu.edit.text = 'Iniciar Validação';
        menu['receive_information'] = {
            text: 'Receber solicitação',
            iconCls: 'icon-core icon-core-refresh',
            scope: this,
            handler: function() { this.receive_information() }
        };
        menu['activeAction'] = {
            text: 'Ativar/Desativar',
            iconCls: 'icon-registration icon-published',
            scope: this,
            handler: function() { this.changeActive() }
        };
        menu['report_form'] = {
            text: 'Relatório',
            iconCls: 'icon-core icon-core-reports',
            scope: this,
            handler: function() {
                Ext._create('rh.registration.forminformation.Report', {}).show();
            }
        };

        return menu;
    },

    filterbyAll: function() {
        var filterState = [1, 2, 3, 4, 5];
        this._fitlerState = filterState;
        this.setFilterProperty('state__in', this._fitlerState, 1000);
        this.removeFilter();
    },

    filterbyValidation: function() {
        var filterState = [2, 3];
        this._fitlerState = filterState;
        this.setFilterProperty('state__in', this._fitlerState, 1000);
        this.removeFilter();
    },

    filterbyValidationProblem: function() {
        var filterState = [4, ];
        this._fitlerState = filterState;
        this.setFilterProperty('state__in', this._fitlerState, 1000);
        this.removeFilter();
    },

    filterbyValidationValidated: function() {
        var filterState = [5, ];
        this._fitlerState = filterState;
        this.setFilterProperty('state__in', this._fitlerState, 1000);
        this.removeFilter();
    },

    filterbyReceived: function() {
        var filterByMe = this.ownerCt.current_user;
        this._filterByMe = filterByMe;
        this.setFilterProperty('received_by__pk', this._filterByMe, 999);
    },

    removeFilter: function(){
        this.removeFilterProperty('received_by__pk', 999);
    },

    getFilterMenu: function() {
        return [
            {
                text: 'Todos',
                scope: this,
                handler: function() { this.filterbyAll(); }
            },
            {
                text: 'Aguardando Validação',
                scope: this,
                handler: function() { this.filterbyValidation(); }
            },
            {
                text: 'Recebidos por mim',
                scope: this,
                handler: function() { this.filterbyReceived(); }
            },
            {
                text: 'Com pendência',
                scope: this,
                handler: function() { this.filterbyValidationProblem(); }
            },
            {
                text: 'Validados',
                scope: this,
                handler: function() { this.filterbyValidationValidated(); }
            },
        ];
    },

    _updateItemCustom: function(record) {
        if(record instanceof Ext.Button)
            record = undefined;
        var selected = core.nullValue(record, this.getSelectionModel().getSelected());
        if(selected && selected.get('state') != 3){
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'É necessário receber a solicitação antes de validar.'
            });
            return;
        }

        if(selected && selected.get('current_user') != selected.get('received_by')){
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Somente quem recebeu o formulário pode validá-lo. Receba novamente para editar!'
            });
            return;
        }

        if(selected) {
            Ext._create('rh.registration.forminformation.admin.Window', {
                action: 'update',
                oId: selected.get('pk'),
                values: 'remote',
                params: this.getParams(),
                selecteDataGridFormInformation: selected.data,
                parentGrid: this,
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                }
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item para editar.'
            });
    },

    receive_information: function(){
        var sels = this.getSelectionModel().getSelections();
        var toReceive = []
        Ext.each(sels, function(record) {
            toReceive.push(record.get('pk'))
        });
        this._receive_information(toReceive);
    },

    _receive_information: function(toReceive){
        var lm = new Ext.LoadMask(this.getEl(), {
            msg: 'Recebendo as informações selecionadas...'
        });
        Ext.Ajax.request({
            scope: this,
            url: toolkit.util.Normalize.controller_action('RegistrationFormInformationAdmin', 'receive_information'),
            params: { pk: toReceive },
            success: function(request) {
                lm.hide();
                this.getStore().reload();
                var rst = Ext.decode(request.responseText);
                if(rst.success == false)
                    Ext.Msg.show({
                        title: 'Item de solicitação',
                        msg: rst.message,
                        icon: Ext.Msg.WARNING,
                        buttons: Ext.Msg.OK
                    });
            },
            failure: function(request) {
                lm.hide();
                this.getStore().reload();
                Ext.Msg.show({
                    title: 'Item de solicitação',
                    msg: 'Ocorreram erros removendo os itens selecionados.',
                    icon: Ext.Msg.WARNING,
                    buttons: Ext.Msg.OK
                });
            }
        })
    },

    changeActive: function(){
        var sels = this.getSelectionModel().getSelections();
        var toAct = []
        Ext.each(sels, function(record) {
            toAct.push(record.get('pk'))
        });

        var lm = new Ext.LoadMask(this.getEl(), {
            msg: 'Recebendo as informações selecionadas...'
        });
        Ext.Ajax.request({
            scope: this,
            url: toolkit.util.Normalize.controller_action('RegistrationFormInformationAdmin', 'change_active'),
            params: { pk: toAct },
            success: function(request) {
                lm.hide();
                this.getStore().reload();
                var rst = Ext.decode(request.responseText);
                if(rst.success == false)
                    Ext.Msg.show({
                        title: 'Item de solicitação',
                        msg: rst.message,
                        icon: Ext.Msg.WARNING,
                        buttons: Ext.Msg.OK
                    });
            },
            failure: function(request) {
                lm.hide();
                this.getStore().reload();
                Ext.Msg.show({
                    title: 'Item de solicitação',
                    msg: 'Ocorreram erros removendo os itens selecionados.',
                    icon: Ext.Msg.WARNING,
                    buttons: Ext.Msg.OK
                });
            }
        })
    },
});

