    getApproverMarkAllFilter: function() {
        if(!this._approverMarkAll) {
            this._approverMarkAll = Ext._create('Ext.menu.CheckItem', {
                text: 'Selecionar Todos',
                scope: this,
                hideOnClick: false,
                checked: false,
                handler: function(checked) {
                    this.getApproverMenuItems().forEach(
                        function (item) {
                            item.setChecked(!checked.checked, true);
                        }
                    );

                    var menuItens = []
                    this.getApproverMenuItems().forEach(function (item) { menuItens.push(item.value); });
                    this.setFilterProperty('step_current__in', menuItens, 1001);
                }
            });
        }
        return this._approverMarkAll;
    },

    getApproverMenuItems: function () {
        if (!this._approverMenuItems) {
            this._approverMenuItems = [];
            for (var i = 0; i < this.approverFilterMenu.length; i++) {
                var item = this.approverFilterMenu[i];
                this._approverMenuItems.push(
                    new Ext.menu.CheckItem({
                        text: item.text,
                        scope: this,
                        hideOnClick: false,
                        checked: item.checked,
                        value: item.value,
                        checkHandler: function (item, checked) { this.toggleApprover(); }
                    })
                );
            }
        }
        return this._approverMenuItems;
    },

    toggleApprover: function () {
        var values = []
        this.getApproverMenuItems().forEach(function (item) { if (item.checked) values.push(item.value); });
        if(values.length == 1 && values.includes(1)){
            this.removeFilterProperty('step_current__in', 1001, false);
            this.setFilterProperty('approver', parseInt(this.params.employee_id), 1001);
        } else {
            this.setFilterProperty('step_current__in', values, 1001);
        }
    },


