    setPreFilterStatus:function(cfg){
        if (cfg.filter_status)
            return [{
                text: 'Aguardando Ciência do Substituto',
                checked:cfg.filter_status.length > 0?this.setCheckedStatus(1,cfg.filter_status):cfg.type_employee == "M"?true:false,
                value: 1
            },
            {
                text: 'Aguardando Assessoria da Corregedoria',
                checked: this.setCheckedStatus(8,cfg.filter_status),
                value: 8
            },
            {
                text: 'Aguardando Aprovador',
                checked: cfg.filter_status.length > 0?this.setCheckedStatus(2,cfg.filter_status):true,
                value: 2
            },
            {
                text: 'Aguardando Efetivação',
                checked: this.setCheckedStatus(3,cfg.filter_status),
                value: 3
            },
            {
                text: 'Efetivado',
                checked: this.setCheckedStatus(4,cfg.filter_status),
                value: 4
            },
            {
                text: 'Indeferido',
                checked: this.setCheckedStatus(5,cfg.filter_status),
                value: 5
            },
            {
                text: 'Cancelado DGP',
                checked: this.setCheckedStatus(6,cfg.filter_status),
                value: 6
            },
            {
                text: 'Cancelado Solicitante',
                checked: this.setCheckedStatus(7,cfg.filter_status),
                value: 7
            },
            {
                text: 'Aguardando Envio',
                checked: this.setCheckedStatus(9,cfg.filter_status),
                value: 9
            },
        ]
    },


    setPreFilterEmployee:function(cfg){
        if (cfg.filter_employee)
            if(cfg.filter_employee == "M"){
                return [
                    {
                        text: 'Servidores',
                        checked: false,
                        value: 'S',
                    },
                    {
                        text: 'Membros',
                        checked: true,
                        value: 'M'
                    },
                    {
                        text: 'Estagiários',
                        checked: false,
                        value: 'E'
                    },
                ]
            }else if (cfg.filter_employee == "S"){
                return [
                    {
                        text: 'Servidores',
                        checked: true,
                        value: 'S',
                    },
                    {
                        text: 'Membros',
                        checked: false,
                        value: 'M'
                    },
                    {
                        text: 'Estagiários',
                        checked: true,
                        value: 'E'
                    },
                ]
            }else{
                return [
                    {
                        text: 'Servidores',
                        checked: true,
                        value: 'S',
                    },
                    {
                        text: 'Membros',
                        checked: true,
                        value: 'M'
                    },
                    {
                        text: 'Estagiários',
                        checked: true,
                        value: 'E'
                    },
                ]
            }
    },


    getColumnModel: function(cfg) {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Código', dataIndex: 'pk', width: 50},
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn',hidden:true},
                    {header: 'Data da Solicitação', dataIndex: 'date', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Tipo da Solicitação', dataIndex: 'type_of_request', width: 250},
                    {header: 'Inicio', dataIndex: 'start_date', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y'),hidden:true},
                    {header: 'Fim', dataIndex: 'end_date', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y'), hidden: true },
                    {header: 'Solicitante', dataIndex: 'request_unicode', width: 120,hidden:true},
                    {header: 'Servidor', dataIndex: 'employee_unicode', width: 120,hidden:true},
                    {header: 'Aprovador Atual', dataIndex: 'custom_approver_current', width: 250},
                    {header: 'Situação', dataIndex: 'status_display', width: 250},
                    {header: 'Aprovador', dataIndex: 'step_current_display', width: 120,hidden:true},
                    {header: 'Saldo', dataIndex: 'balance', width: 120,hidden:true}
                ]
            );

        return this._columnModel;
    },

    getUpdateAction:function(){
        return{
            text: 'Alterar',
            scope: this,
            iconCls: true,
            icon: '/' + global.Context + '/static/rh/images/edit.png',
            handler: function () {
                this.updateItem();
            }
        }

    },

    getCancelAction:function(){
        return{
            text: 'Cancelar Solicitação',
            scope: this,
            iconCls: true,
            icon: '/' + global.Context + '/static/rh/images/denied.png',
            handler: function () {
                if (this.getSelectionModel().getSelected()) {
                    var cod = this.getSelectionModel().getSelected().id
                    var type = this.getSelectionModel().getSelected().data.type_of_request
                    Ext.Msg.show({
                        title:"Cancelar Solicitação",
                        icon: Ext.Msg.QUESTION,
                        buttons: Ext.Msg.YESNO,
                        msg: 'Deseja mesmo cancelar a solicitação de '+type+" Código: "+cod+' ?',
                        scope: this,
            
                        fn: function (btn) {
                            if (btn == 'no') return;
                            var params = {
                                pk: cod,
                            };
                            this._cancel(params);
                        }
                    });
                   
                } else {
                    Ext.Msg.show({
                        title: "Cancelar",
                        msg: "Selecione uma Solicitação!",
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                    });
                }
            }
        }

    },

