                    var tests = [
                        /^$/,
                        /^[0-2]$/,
                        /^([0-1][0-9]|2[0-3])$/,
                        /^([0-1][0-9]|2[0-3]):$/,
                        /^([0-1][0-9]|2[0-3]):[0-5]$/,
                        /^([0-1][0-9]|2[0-3]):[0-5][0-9]$/,
                    ];

                    var flag = true;
                    Ext.each(tests, function(t) {
                        if(t.test(value)) {
                            flag = true;
                            return false;
                        }
                    });

                    return (flag ? true : 'Horário informado é inválido.');
