Ext._define('rh.cadastralquality.Restful', {
    extend: 'core.Restful',

    resource: 'QRegistration',

    getFields: function(cfg) {
        if(!this._fields)
            this._fields = rh.cadastralquality.Restful.superclass.getFields.call(this, cfg).concat([
                {
                    name: 'icons'
                },
                {
                    name: "title",
                    type: "string"
                },
                {
                    name: "description",
                    type: "string"
                }
            ]);

        return this._fields;
    },

    _report: function (params, cbSuccess, cbFailure, cbCallback) {
        var emptyFailure = {
            fn: function (message) {
                Ext.Msg.show({
                    title: 'Processando',
                    icon: Ext.Msg.WARNING,
                    buttons: Ext.Msg.OK,
                    msg: message
                });
            }
        };
        
        this.doRequest(this.getRoute(
            'full_report',
            null,
            'POST',
            {
                params,
                success: function (xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if (rst.success) {
                        Ext.Msg.show({
                            title: 'Solicitando Relatório',
                            msg: rst.message,
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK
                        });
                        core.invokeCallback((cbSuccess || { fn: Ext.emptyFn }), rst.message);
                    } else
                        core.invokeCallback((emptyFailure || { fn: Ext.emptyFn }), rst.message);
                },
                failure: function (xhr) {
                    var rst = Ext.decode(xhr.responseText);
                    core.invokeCallback((cbFailure || emptyFailure), 'Recurso indisponivel no momento.');
                },
                callback: function () {
                    core.invokeCallback((cbCallback || { fn: Ext.emptyFn }));
                }
            }
        ));
    },
});

