 Ext._define('rh.gratifications_manager.gratifications.workplace_tag.Grid', {

    extend: 'rh.workplace.WorkplaceConfigTagGrid',

    rest: 'rh.gratifications_manager.gratifications.workplace_tag.Restful',
   
    restWindow: 'rh.gratifications_manager.gratifications.workplace_tag.Window',

    keywordFieldWidth: 120,

    configOrderToolBar: ['confirmar_selecionados','confirmar_todos','download'],

    hideActions: ['edit', 'remove', 'copy'],

    doDownload: function() {
        var filtro_conferencia = 'todos';
        this._toolbar.items.items.forEach(function(item){
            if(item.text == 'Filtrar Conferência'){
                item.menu.items.items.forEach(function(item_menu){
                    if(item_menu.checked){ filtro_conferencia = item_menu.id; }
                });
            }
        });

        var config = {
            servidor_id: this.params.servidor,
            year: this.params.year,
            month: this.params.month,
            filter: Ext.encode(this.getFilter()),
            keyword: this.getKeywordField().getValue(),
            start: 0,
            limit: this.getStore().getTotalCount(),
            filtro_conferencia: filtro_conferencia,
            format: 'text/csv'
        };

        var rest = this.factoryRestful();
        var url = rest.getRoute('export').url + '?' + Ext.urlEncode(config);

        window.open(url, '_self');
    },
    
    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: '', dataIndex: 'icons', sortable: true, width: 75, menuDisabled: true, renderer: toolkit.util.formatStatus },
                    {header: 'Gratificação', dataIndex: 'unicode', id: 'autoExpandColumn'},
                    {header: 'Dias a Receber', dataIndex: 'calculate_days', width: 120}
                ]
            );

        return this._columnModel;
    },

    getToolbar: function(cfg) {
        if(!this._toolbar){
            var itensTollBar = this.getConfigItemsToolbar(cfg);
            
            itensTollBar.splice(2, 0, '->');
            
            var menuFiltroConferencia = this.menuFiltroConferencia(cfg);
            itensTollBar.splice(
                3,
                0,
                {
                    text: 'Filtrar Conferência',
                    iconCls: 'icon-patrimonio icon-pat-filter',
                    menu: menuFiltroConferencia,
                }
            )

            this._toolbar = Ext._create('Ext.Toolbar', {
                style: cfg.toolbarStyle,
                items: itensTollBar,
            });

            if((this.toolbarHideLabel || cfg.toolbarHideLabel))
                this._toolbar.items.each(
                    function(item) {
                        item.tooltip = (item.tooltip || item.text);

                        if(item.text && core.nullValue(item.hideLabel, true))
                            item.text = null;
                    }
                );
        }

        return this._toolbar;
    },

    menuFiltroConferenciaItem: function(cfg, id, texto, checked){
        return {
            id: id,
            text: texto,
            checked: checked,
            scope: this,
            hideOnClick: false,
            handler: function(chk) { this.filtrarConferencia(cfg, chk, id) },
        }
    },

    menuFiltroConferencia: function(cfg){
        var _menuFiltroStatus = [
            this.menuFiltroConferenciaItem(cfg, 'todos', 'Todos', true),
            this.menuFiltroConferenciaItem(cfg, 'conferido', 'Conferidos', false),
            this.menuFiltroConferenciaItem(cfg, 'nao_conferido', 'Não Conferidos', false),
        ];

        return _menuFiltroStatus;
    },

    filtrarConferencia: function(cfg, chk, opcao){
        if(!chk.checked == true){
            this._toolbar.activeMenuBtn.menu.items.items.forEach(function(item){
                if(item.id != opcao && item.checked == true){
                    item.setChecked(false);
                }
            });

            this.getStore().baseParams['filtro_conferencia'] = opcao;
        }else if(!chk.checked == false && opcao == 'todos'){
            this.getStore().baseParams['filtro_conferencia'] = 'conferido';

            this._toolbar.activeMenuBtn.menu.items.items.forEach(function(item){
                if(item.id == 'conferido'){
                    item.setChecked(true);
                }else if(item.id != opcao){
                    item.setChecked(false);
                }
            });
        }
        
        if(this.getStore().lastOptions.params){
            delete this.getStore().lastOptions.params.start;
            delete this.getStore().lastOptions.params.limit;
        }
        
        this.getStore().load();
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-fopag icon-ui-toolbar-pencil',
                tooltip: 'Conferir',
                scope: this,
                handler: function(action, index){ this._confirmarGratificacao(action._store.getAt(index).data) },
            },
        ];
    },

    _requestConfirmacao: function(nome_metodo, params){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action('WorkplaceTag',nome_metodo),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                Ext.Msg.show({
                    width:"400px",
                    title: this.title,
                    icon: Ext.Msg.INFO,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){ this.getStore().reload(); }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

    _confirmarGratificacao: function(gratificacao){
        xt.Msg.show({
            msg: 'Realizou a análise? Tem certeza que deseja realizar conferência para a Gratificação selecionada?',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                if(gratificacao.calculate_days == '-'){
                    var msg = 'Não é possível realizar conferência para a Gratificação selecionada. ';
                    msg += 'Não há cálculos para a Gratificação selecionada';
                    Ext.Msg.show({
                        title: this.title,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: msg
                    });
                    return false;
                }
                else{
                    var params = {
                        periodo_ano: gratificacao.periodo_ano,
                        periodo_mes: gratificacao.periodo_mes,
                        servidor_id: gratificacao.servidor_id,
                        evento_numero: gratificacao.evento_numero,
                        qtd_dias: gratificacao.calculate_days,
                    }
                    this._requestConfirmacao('conferir_gratificacao', params)
                }
            }
        })
    },

    _confirmarGratificacoes: function(tipo_selecao){
        if(tipo_selecao == 'todos'){
            var items = this.getSelectionModel().grid.store.data.items;
        }else{
            var items = this.getSelectionModel().getSelections();    
        }

        var gratificacoes = [];
        items.map(function(gratificacao){
            var conferido = false;
            var icons_gratif = gratificacao.data.icons;
            if(icons_gratif.length > 0){
                icons_gratif.forEach(function(item_gratif){
                    if(item_gratif.title == 'Conferido'){ conferido = true; }
                })
            }

            if(conferido == false){
                var qtd_dias = gratificacao.data.calculate_days
                if(qtd_dias != '-'){
                    gratificacoes.push({
                        'periodo_ano': gratificacao.data.periodo_ano,
                        'periodo_mes': gratificacao.data.periodo_mes,
                        'servidor_id': gratificacao.data.servidor_id,
                        'evento_numero': gratificacao.data.evento_numero,
                        'qtd_dias': qtd_dias,
                    });
                }
            }
        });

        if(gratificacoes.length == 0){
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Escolha pelo menos um registro para conferir.'
            });
        }else{
            Ext.Msg.show({
                msg: 'Tem certeza que deseja confirmar as gratificações (serão confirmadas somente os registros válidos)?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function (b) {
                    if (b == 'no') return;

                    var params = { gratificacoes: JSON.stringify(gratificacoes) }
                    this._requestConfirmacao('conferir_lista_gratificacoes', params)
                }
            })
        }
    },

    getConfigActionsItems: function(cfg){
        var menu = rh.gfp.payroll.EventGrid.superclass.getConfigActionsItems.call(this, cfg);

        menu['confirmar_selecionados'] = {
            text: 'Conferir Selecionados',
            iconCls: 'icon-fopag icon-ui-toolbar-pencil',
            scope: this,
                handler: function(){ this._confirmarGratificacoes('selecionados') },
        };

        menu['confirmar_todos'] = {
            text: 'Conferir Todos',
            iconCls: 'icon-fopag icon-ui-toolbar-arrow',
            scope: this,
            handler: function(){ this._confirmarGratificacoes('todos') },
        };
        
        return menu;
    },
});

