    REGION: 'center',
    GAP: 50,
    LEFT_PADDING: 375,
    BOTTOM_PADDING: 100,

    REPORT_CLASS: 'ProvideEntryReport',
    PDF_FUNCTION: 'generate_provider_entry_pdf',
